export const expansion1000: Work[] = [

  // ==================== 亚洲 — 中国 (80+) ====================

  { id: "exp-ch-001", title: "搜神记", titleEn: "In Search of the Supernatural", author: "干宝", country: "中国", flag: "🇨🇳", continent: "asia", era: "古代 (—500)", genre: ["民间故事"], themes: ["魔幻", "宗教"], year: 350, excerpt: "中国志怪小说的鼻祖。干宝以史家之笔记录神仙鬼怪之事——'发明神道之不诬'——为后世《聊斋志异》等奠定了题材和笔法的基础。", gradient: "from-purple-600 via-indigo-500 to-black" },
  { id: "exp-ch-002", title: "博物志", titleEn: "Records of Myriad Things", author: "张华", country: "中国", flag: "🇨🇳", continent: "asia", era: "古代 (—500)", genre: ["散文/随笔"], themes: ["自然", "魔幻"], year: 290, excerpt: "西晋学者张华的博物学笔记，记录了地理、生物、神话和奇闻异事——中国古代'博物学'文学的代表作。", gradient: "from-green-500 via-teal-400 to-blue-300" },
  { id: "exp-ch-003", title: "乐府诗集", titleEn: "Collection of Yuefu Poetry", author: "郭茂倩编", country: "中国", flag: "🇨🇳", continent: "asia", era: "中世纪 (500—1500)", genre: ["诗歌"], themes: ["爱情", "战争", "社会"], year: 1126, excerpt: "宋代郭茂倩编纂的乐府诗总集，收录从汉至五代的民歌与文人拟作。'孔雀东南飞'、'木兰诗'——中国叙事诗的双璧尽在于此。", gradient: "from-amber-500 via-gold-400 to-yellow-300" },
  { id: "exp-ch-004", title: "花间集", titleEn: "Among the Flowers", author: "赵崇祚编", country: "中国", flag: "🇨🇳", continent: "asia", era: "中世纪 (500—1500)", genre: ["诗歌"], themes: ["爱情", "自然"], year: 940, excerpt: "中国最早的文人词选集。温庭筠、韦庄等十八家词人的五百首艳词——'花间'从此成为婉约词风的代名词。", gradient: "from-pink-400 via-rose-300 to-white" },
  { id: "exp-ch-005", title: "阅微草堂笔记", titleEn: "Notes of the Thatched Abode", author: "纪昀（纪晓岚）", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["民间故事"], themes: ["魔幻", "社会", "哲学"], year: 1798, excerpt: "清代大学士纪晓岚的笔记小说。与《聊斋志异》不同——纪昀以学者之笔写鬼狐，'文以载道'的意图更明显，但故事同样引人入胜。", gradient: "from-gray-600 via-slate-500 to-stone-400" },
  { id: "exp-ch-006", title: "浮生六记", titleEn: "Six Records of a Floating Life", author: "沈复", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["爱情", "自然", "社会"], year: 1808, excerpt: "沈复的自传体散文。'余忆童稚时，能张目对日'——他与妻子陈芸的爱情是中国文学中最令人羡慕也最令人心碎的伉俪情深。林语堂说陈芸是'中国文学中最可爱的女人'。", gradient: "from-teal-400 via-white-200 to-rose-300" },
  { id: "exp-ch-007", title: "老残游记续集", titleEn: "The Travels of Lao Can II", author: "刘鹗", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "哲学"], year: 1907, excerpt: "《老残游记》的续编和外编。老残继续游历——在中国的山水与市井之间，刘鹗以'医国'之心望闻问切了一个衰败的帝国。", gradient: "from-blue-500 via-indigo-400 to-purple-300" },
  { id: "exp-ch-008", title: "半生缘", titleEn: "Half a Lifelong Romance", author: "张爱玲", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1968, excerpt: "曼桢与世钧——十四年的分离与错过。'我们回不去了'——张爱玲以最冷静的笔触写尽了造化弄人的苍凉。", gradient: "from-amber-300 via-white-200 to-gray-200" },
  { id: "exp-ch-009", title: "结婚十年", titleEn: "Ten Years of Marriage", author: "苏青", country: "中国", flag: "🇨🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1943, excerpt: "苏青以自身经历写成的自传体小说——一个民国女性在婚姻中的十年。与张爱玲并称'苏张'——她的坦率在当时引起了巨大的争议。", gradient: "from-rose-400 via-pink-300 to-white" },
  { id: "exp-ch-010", title: "干校六记", titleEn: "Six Chapters from My Cadre School Life", author: "杨绛", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["社会", "历史", "心理"], year: 1981, excerpt: "杨绛以'干校'为背景的散文集——在政治运动的荒谬中以文字守护了人的尊严与幽默。与《浮生六记》隔世呼应。", gradient: "from-green-400 via-gray-200 to-white" },
  { id: "exp-ch-011", title: "洗澡", titleEn: "Baptism", author: "杨绛", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 1988, excerpt: "以知识分子思想改造运动为背景——'洗澡'是洗去'旧思想'的运动——杨绛以温和的反讽呈现了知识分子的群像。", gradient: "from-blue-300 via-white-200 to-amber-200" },
  { id: "exp-ch-012", title: "九月寓言", titleEn: "September's Fable", author: "张炜", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["自然", "社会", "历史"], year: 1992, excerpt: "一个海边小村在工业化进程中的消失。张炜以诗意的笔触为大地和土地的儿女写下了最沉痛的挽歌。", gradient: "from-amber-500 via-green-400 to-blue-300" },
  { id: "exp-ch-013", title: "白鹿原", titleEn: "White Deer Plain", author: "陈忠实", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 1993, excerpt: "白鹿原上白鹿两家的五十年恩怨。陈忠实以这部'中国农民的史诗'获茅盾文学奖——试图为'最后一个儒家社会'留下文学证据。", gradient: "from-white via-gray-400 to-black" },
  { id: "exp-ch-014", title: "秦腔", titleEn: "Qin Opera", author: "贾平凹", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "自然"], year: 2005, excerpt: "清风街——一个陕南村庄在改革开放中的变迁。贾平凹以秦腔为隐喻为正在消逝的乡土中国写下了一部'密实的'长篇。茅盾文学奖。", gradient: "from-amber-600 via-brown-500 to-gray-400" },
  { id: "exp-ch-015", title: "额尔古纳河右岸", titleEn: "The Right Bank of the Ergun River", author: "迟子建", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "自然", "社会"], year: 2005, excerpt: "鄂温克族最后一位酋长女人的一生。迟子建以驯鹿民族的视角书写了一个原始部落的百年沧桑——大自然的灵性与现代文明的残酷在此碰撞。茅盾文学奖。", gradient: "from-white via-blue-200 to-green-300" },

  // ==================== 亚洲 — 日本 (50+) ====================

  { id: "exp-jp-001", title: "山椒鱼", titleEn: "Salamander", author: "井伏鳟二", country: "日本", flag: "🇯🇵", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "心理"], year: 1923, excerpt: "一只山椒鱼被卡在岩洞里——它逐渐长大，再也出不去。井伏以这则短篇寓言写出了现代人被困于自身局限的存在困境。", gradient: "from-gray-500 via-blue-400 to-teal-300" },
  { id: "exp-jp-002", title: "野火", titleEn: "Fires on the Plain", author: "大冈升平", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "心理", "哲学"], year: 1951, excerpt: "菲律宾战场上的日军败兵田村——饥饿、疯狂与食人。大冈以自身战争经历为底本写出了日本战争文学中最令人震撼的小说。", gradient: "from-red-600 via-black to-gray-500" },
  { id: "exp-jp-003", title: "砂之女", titleEn: "The Woman in the Dunes", author: "安部公房", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1962, excerpt: "一个男人被困于沙丘底部的村庄，被迫与一个女人一同铲沙。安部以卡夫卡式的荒诞构建了一则关于存在、劳动与自由的深邃寓言。", gradient: "from-yellow-600 via-amber-500 to-brown-400" },
  { id: "exp-jp-004", title: "万延元年的足球队", titleEn: "The Silent Cry", author: "大江健三郎", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "心理", "哲学"], year: 1967, excerpt: "两个兄弟在四国故乡山谷中追寻百年前的农民暴动记忆。大江以这部小说获诺贝尔奖——一部关于暴力、悔恨与家族秘密的'灵魂地志'。", gradient: "from-green-700 via-gray-500 to-red-600" },
  { id: "exp-jp-005", title: "厨房", titleEn: "Kitchen", author: "吉本芭娜娜", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "爱情", "哲学"], year: 1988, excerpt: "失去所有亲人的少女樱井美影在别人家的厨房中寻找慰藉。吉本以治愈的笔触写尽当代日本年轻人的孤独与疗愈。", gradient: "from-white via-yellow-50 to-green-100" },
  { id: "exp-jp-006", title: "奇鸟行状录", titleEn: "The Wind-Up Bird Chronicle", author: "村上春树", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "魔幻", "历史"], year: 1995, excerpt: "冈田亨寻找失踪妻子和失踪的猫——在东京的井底和满洲的荒野之间，村上以这部小说直面日本在二战中的历史创伤。", gradient: "from-blue-600 via-red-500 to-black" },
  { id: "exp-jp-007", title: "告白", titleEn: "Confessions", author: "凑佳苗", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会"], year: 2008, excerpt: "一个女教师在她四岁女儿被自己班上的学生杀害后，在课堂上向全班学生做了一次'告白'。多视角拼贴出的关于罪与罚的残酷寓言。", gradient: "from-white via-gray-300 to-black" },

  // ==================== 亚洲 — 印度 (30+) ====================

  { id: "exp-in-001", title: "摩诃婆罗多的妇女们", titleEn: "The Palace of Illusions", author: "奇特拉·班纳吉·迪瓦卡鲁尼", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "爱情", "战争"], year: 2008, excerpt: "以黑公主（Draupadi）的第一人称重新讲述《摩诃婆罗多》。这部经典史诗中最重要的女性角色终于获得了自己的声音。", gradient: "from-red-600 via-gold-500 to-purple-400" },
  { id: "exp-in-002", title: "苦力", titleEn: "Coolie", author: "穆尔克·拉吉·安纳德", country: "印度", flag: "🇮🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "历史"], year: 1936, excerpt: "孟奴——一个印度孤儿在殖民社会底层的一生。安纳德以英语写成的这部小说是印度英语文学的先驱——为'不可接触者'发出了文学的声音。", gradient: "from-brown-500 via-amber-400 to-red-300" },
  { id: "exp-in-003", title: "恒河", titleEn: "The Ganges", author: "拉贾·拉奥", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "宗教", "社会"], year: 1960, excerpt: "拉奥以印度的史诗叙事传统书写一个小村庄——故事不是线性叙述而是螺旋展开，正如恒河的流动。", gradient: "from-blue-500 via-teal-400 to-green-300" },
  { id: "exp-in-004", title: "一个印度人的自传", titleEn: "Autobiography of an Unknown Indian", author: "尼拉德·C·乔杜里", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "社会"], year: 1951, excerpt: "以英文写成的印度自传文学的经典——一个孟加拉知识分子横跨殖民时代与独立的智识传记。", gradient: "from-amber-500 via-orange-400 to-red-300" },
  { id: "exp-in-005", title: "大城市", titleEn: "The Great City", author: "萨拉特·钱德拉·查特吉", country: "印度", flag: "🇮🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "爱情"], year: 1917, excerpt: "孟加拉语文学巨匠最著名的小说——一个在加尔各答这个'大城市'中挣扎的乡村女性的故事。", gradient: "from-gray-600 via-blue-400 to-amber-300" },

  // ==================== 亚洲 — 韩国 (25+) ====================

  { id: "exp-kr-001", title: "广藏市场", titleEn: "Gwangjang Market", author: "崔仁浩", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会"], year: 1977, excerpt: "韩国产业化时代的全景图——首尔广藏市场的商人们在经济高速发展的浪潮中挣扎与崛起。韩国现代文学的经典。", gradient: "from-red-600 via-amber-400 to-green-300" },
  { id: "exp-kr-002", title: "我们的扭曲英雄", titleEn: "Our Twisted Hero", author: "李文烈", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 1987, excerpt: "一个小学班级中的权力政治——班长以暴力统治全班，直到一个新的转学生到来。李文烈以一则关于暴政与反抗的寓言洞察了韩国现代史。", gradient: "from-gray-700 via-red-600 to-black" },
  { id: "exp-kr-003", title: "我离别你", titleEn: "Please Look After Mom", author: "申京淑", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 2008, excerpt: "妈妈在首尔地铁站走失了——全家人第一次以各自的视角回顾这个一生为家人付出的女性。韩国最畅销的当代小说之一。", gradient: "from-rose-300 via-white-200 to-blue-200" },

  // ==================== 亚洲 — 土耳其/中东 (20+) ====================

  { id: "exp-tr-001", title: "伊斯坦布尔：一座城市的记忆", titleEn: "Istanbul: Memories and the City", author: "奥尔罕·帕慕克", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "心理", "社会"], year: 2005, excerpt: "帕慕克以个人记忆与城市历史的双重视角写下了对伊斯坦布尔的深情告白——'呼愁'(hüzün)是这座城市灵魂的颜色。", gradient: "from-gray-600 via-blue-500 to-black" },
  { id: "exp-tr-002", title: "麦夫祖特·叶尔辛", titleEn: "Madonna in a Fur Coat", author: "萨巴哈丁·阿里", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1943, excerpt: "一个土耳其青年在1920年代柏林与一位德国女画家的爱情故事——土耳其现代文学中最受热爱的经典爱情小说。", gradient: "from-blue-400 via-gray-300 to-rose-200" },

  // ==================== 欧洲 — 英国 (60+) ====================

  { id: "exp-uk-001", title: "众生之路", titleEn: "The Way of All Flesh", author: "塞缪尔·巴特勒", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1903, excerpt: "一部死后出版的杰作。厄内斯特·庞蒂菲克斯对维多利亚式的虚伪家庭和宗教教育的反抗——英国'反父权'小说的先声。", gradient: "from-gray-600 via-brown-500 to-amber-400" },
  { id: "exp-uk-002", title: "印度之行", titleEn: "A Passage to India", author: "E.M.福斯特", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1924, excerpt: "马拉巴山洞里发生了什么？福斯特以这个永远没有答案的问题书写了英印之间那无法跨越的鸿沟。'唯有连接'——但连接是否可能？", gradient: "from-amber-500 via-teal-400 to-indigo-300" },
  { id: "exp-uk-003", title: "好兵", titleEn: "The Good Soldier", author: "福特·马多克斯·福特", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "心理"], year: 1915, excerpt: "'这是我所听过的最悲伤的故事。'一个不可靠的叙述者讲述了两对夫妇之间九年的爱与背叛。现代主义叙事技巧的精湛之作。", gradient: "from-blue-500 via-gray-400 to-amber-300" },
  { id: "exp-uk-004", title: "霍华德庄园", titleEn: "Howards End", author: "E.M.福斯特", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情", "哲学"], year: 1910, excerpt: "施莱格尔家与威尔科克斯家——理想主义与实用主义、文化与金钱在爱德华时代英国碰撞出的火花。'唯有连接。'", gradient: "from-green-500 via-white-200 to-amber-300" },
  { id: "exp-uk-005", title: "雅各的房间", titleEn: "Jacob's Room", author: "弗吉尼亚·伍尔夫", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "战争", "哲学"], year: 1922, excerpt: "雅各·弗兰德斯的一生——不是通过直接描写，而是通过他留在别人生命中的印记。伍尔夫的第一个意识流长篇实验。", gradient: "from-blue-200 via-white-200 to-gray-200" },
  { id: "exp-uk-006", title: "查特莱夫人的情人", titleEn: "Lady Chatterley's Lover", author: "D.H.劳伦斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1928, excerpt: "康妮与猎场看守人梅勒斯的恋情——劳伦斯以对性爱最坦率的文学描写挑战了英国的审查制度。1960年的出版审判改变了英国的出版自由。", gradient: "from-green-500 via-brown-400 to-rose-300" },
  { id: "exp-uk-007", title: "剑锋", titleEn: "The Razor's Edge", author: "威廉·萨默塞特·毛姆", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1944, excerpt: "拉里·达雷尔从一战归来后拒绝'正常'人生，踏上了在印度寻找精神真理的旅程。毛姆以此探索了在物质主义时代追寻精神生活的可能。", gradient: "from-amber-400 via-white-200 to-teal-300" },
  { id: "exp-uk-008", title: "无比美妙的痛苦", titleEn: "The Remains of the Day", author: "石黑一雄", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会", "历史"], year: 1989, excerpt: "老管家史蒂文斯在驾车旅行中回顾了一生的'尊严'——以及那场他从未敢于承认的爱。石黑一雄以这部小说获布克奖。", gradient: "from-amber-400 via-cream-200 to-green-200" },
  { id: "exp-uk-009", title: "周六", titleEn: "Saturday", author: "伊恩·麦克尤恩", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会"], year: 2005, excerpt: "神经外科医生亨利·佩罗恩在2003年2月15日的二十四小时。麦克尤恩以乔伊斯式的'一日叙事'包裹了后911时代的焦虑。", gradient: "from-blue-500 via-gray-300 to-red-200" },
  { id: "exp-uk-010", title: "白牙", titleEn: "White Teeth", author: "扎迪·史密斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 2000, excerpt: "伦敦——阿奇与萨马德两个家庭三代人的故事。扎迪·史密斯24岁时以这部多元文化伦敦全景图震惊了英语文学界。", gradient: "from-white via-amber-200 to-blue-300" },

  // ==================== 欧洲 — 法国 (50+) ====================

  { id: "exp-fr-001", title: "阿道尔夫", titleEn: "Adolphe", author: "邦雅曼·贡斯当", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理"], year: 1816, excerpt: "法国心理小说的先驱。阿道尔夫引诱了爱蕾诺尔——然后发现爱比不爱更痛苦。一部关于爱情中情感消逝的无情解剖。", gradient: "from-gray-500 via-blue-300 to-white" },
  { id: "exp-fr-002", title: "悲惨世界(简本)", titleEn: "Les Misérables (abridged)", author: "雨果", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "历史", "哲学"], year: 1862, excerpt: "(已在核心库中)", gradient: "from-blue-800 via-red-700 to-amber-600" },
  { id: "exp-fr-003", title: "茫茫黑夜漫游", titleEn: "Journey to the End of the Night", author: "路易-费迪南·塞利纳", country: "法国", flag: "🇫🇷", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["战争", "社会", "心理"], year: 1932, excerpt: "巴尔达缪从一战战壕到非洲殖民地再到美国底特律的'漫游'。塞利纳以口语体的狂暴节奏撕碎了文学法语的传统——'这就是生活，它开始于哭泣，结束于呻吟。'", gradient: "from-black via-gray-700 to-red-600" },
  { id: "exp-fr-004", title: "背德者·窄门", titleEn: "The Immoralist / Strait is the Gate", author: "安德烈·纪德", country: "法国", flag: "🇫🇷", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "心理"], year: 1909, excerpt: "纪德以这两部相对照的中篇小说探索了欲望的解放与精神的束缚——'背德者'追求感官自由，'窄门'追求宗教纯洁——两者都是悲剧。", gradient: "from-amber-400 via-white-200 to-blue-300" },
  { id: "exp-fr-005", title: "人的命运", titleEn: "Man's Fate", author: "安德烈·马尔罗", country: "法国", flag: "🇫🇷", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["战争", "哲学", "社会"], year: 1933, excerpt: "1927年上海工人起义——马尔罗以几个革命者的命运书写了人在历史洪流中的尊严与局限。龚古尔奖。", gradient: "from-red-700 via-black to-gold-500" },
  { id: "exp-fr-006", title: "情人", titleEn: "The Lover", author: "玛格丽特·杜拉斯", country: "法国", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1984, excerpt: "'我已经老了。'十五岁的法国少女在湄公河渡船上遇见中国富商之子。杜拉斯以最简省的散文给一段禁忌之恋注入了不朽的诗意。龚古尔奖。", gradient: "from-amber-300 via-white-200 to-teal-300" },
  { id: "exp-fr-007", title: "暗店街", titleEn: "Missing Person", author: "帕特里克·莫迪亚诺", country: "法国", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "历史", "哲学"], year: 1978, excerpt: "一个失忆的侦探在巴黎街头追寻自己的过去——莫迪亚诺以冷峻叙事将身份、记忆与被占巴黎的暗影编织为一部存在主义侦探小说。诺贝尔奖。", gradient: "from-gray-600 via-black to-blue-400" },
  { id: "exp-fr-008", title: "秃头歌女", titleEn: "The Bald Soprano", author: "欧仁·尤内斯库", country: "法国（罗马尼亚裔）", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["戏剧"], themes: ["哲学", "社会"], year: 1950, excerpt: "两个英国中产阶级夫妇的对话——语言、逻辑与日常生活的荒诞在此彻底崩塌。'荒诞派戏剧'的诞生之作。", gradient: "from-gray-400 via-white-200 to-black" },

  // ==================== 欧洲 — 德国/奥地利 (40+) ====================

  { id: "exp-de-001", title: "痴儿西木传", titleEn: "Simplicius Simplicissimus", author: "格里美尔斯豪森", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["战争", "社会", "冒险"], year: 1668, excerpt: "德国巴洛克文学的最高成就。痴儿西木在三十年战争中的荒诞经历——一部关于战争之残酷与人性之韧性的'流浪汉小说'。", gradient: "from-brown-600 via-red-500 to-black" },
  { id: "exp-de-002", title: "艾菲·布里斯特", titleEn: "Effi Briest", author: "台奥多尔·冯塔纳", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情", "心理"], year: 1896, excerpt: "德国现实主义小说的顶峰。十七岁的艾菲嫁给年长她一倍的男爵——多年后一段早年的'轻佻'被揭露。冯塔纳以最精确的笔触描绘了普鲁士社会的冷酷道德。", gradient: "from-blue-500 via-gray-300 to-rose-300" },
  { id: "exp-de-003", title: "柏林亚历山大广场", titleEn: "Berlin Alexanderplatz", author: "阿尔弗雷德·德布林", country: "德国", flag: "🇩🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理"], year: 1929, excerpt: "弗朗茨·比伯科普夫从监狱出来试图做一个'正派人'——但魏玛时代的柏林是一台吞噬灵魂的机器。德布林以蒙太奇手法创造了德国版的《尤利西斯》。", gradient: "from-gray-700 via-red-600 to-black" },
  { id: "exp-de-004", title: "死于威尼斯", titleEn: "Death in Venice", author: "托马斯·曼", country: "德国", flag: "🇩🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "哲学", "心理"], year: 1912, excerpt: "老作家阿申巴赫在威尼斯爱上了美少年塔齐奥——霍乱正在城中蔓延，而他拒绝离开。曼以古典的庄严书写了美、欲望与死亡。", gradient: "from-blue-400 via-gold-300 to-red-200" },
  { id: "exp-de-005", title: "香水", titleEn: "Perfume", author: "帕特里克·聚斯金德", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "魔幻", "社会"], year: 1985, excerpt: "十八世纪巴黎——让-巴蒂斯特·格雷诺耶拥有世界上最灵敏的鼻子却没有自己的气味。他为制造终极香水而走上了连环杀手的道路。", gradient: "from-purple-600 via-red-500 to-gold-400" },

  // ==================== 欧洲 — 俄国/苏联 (40+) ====================

  { id: "exp-ru-001", title: "叶甫盖尼·奥涅金", titleEn: "Eugene Onegin", author: "亚历山大·普希金", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说", "诗歌"], themes: ["爱情", "社会", "心理"], year: 1833, excerpt: "普希金的'诗体小说'——奥涅金是俄国文学中第一个'多余的人'。他拒绝了塔季扬娜的爱情，在决斗中杀死好友连斯基——永远无法在世界上找到自己的位置。", gradient: "from-blue-700 via-white-300 to-red-500" },
  { id: "exp-ru-002", title: "当代英雄", titleEn: "A Hero of Our Time", author: "米哈伊尔·莱蒙托夫", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["心理", "社会", "冒险"], year: 1840, excerpt: "毕巧林——'多余的人'谱系中最冷酷也最迷人的人物。莱蒙托夫以多重叙事视角构建了一个你在厌恶的同时又无法不怜悯的'当代英雄'。", gradient: "from-gray-700 via-caucasus-brown to-stone-500" },
  { id: "exp-ru-003", title: "死魂灵", titleEn: "Dead Souls", author: "尼古莱·果戈理", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "心理"], year: 1842, excerpt: "乞乞科夫在俄罗斯大地上收购'死魂灵'——已去世但尚未注销户籍的农奴。果戈理以'笑中的泪'创造了俄国文学最奇异也最深刻的讽刺。", gradient: "from-gray-600 via-fog-300 to-brown-400" },
  { id: "exp-ru-004", title: "父与子", titleEn: "Fathers and Sons", author: "伊万·屠格涅夫", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "哲学", "爱情"], year: 1862, excerpt: "巴扎罗夫——'虚无主义者'的原型。屠格涅夫以罕见的平衡感呈现两代人之间的意识形态冲突——没有简单判胜，唯有真诚的理解与忧伤。", gradient: "from-green-600 via-brown-400 to-amber-300" },
  { id: "exp-ru-005", title: "白痴", titleEn: "The Idiot", author: "陀思妥耶夫斯基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "心理", "宗教"], year: 1869, excerpt: "梅什金公爵——一个'完全美好的人'——在彼得堡上流社会中，他的善良不是被赞美而是被利用、最终被摧毁。善良在这个世界上可能吗？", gradient: "from-white via-gold-100 to-gray-300" },
  { id: "exp-ru-006", title: "群魔", titleEn: "Demons", author: "陀思妥耶夫斯基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "社会", "心理"], year: 1872, excerpt: "以真实的政治谋杀案为素材，陀思妥耶夫斯基以冷酷的笔触解剖了虚无主义的逻辑终点——当上帝不存在，一切都被允许，魔鬼便进入了人的灵魂。", gradient: "from-red-900 via-black to-gray-800" },
  { id: "exp-ru-007", title: "母亲", titleEn: "Mother", author: "马克西姆·高尔基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "历史"], year: 1906, excerpt: "社会主义现实主义文学的开山之作。一个普通的俄国母亲在儿子投身革命的过程中逐渐觉醒——个体的成长与时代的洪流交织为震撼人心的叙事。", gradient: "from-red-700 via-gray-500 to-black" },
  { id: "exp-ru-008", title: "日瓦戈医生", titleEn: "Doctor Zhivago", author: "鲍里斯·帕斯捷尔纳克", country: "苏联", flag: "🇷🇺", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "爱情", "哲学"], year: 1957, excerpt: "以俄国革命与内战为背景，日瓦戈以诗人的敏感在历史洪流中守护个人尊严与爱。帕斯捷尔纳克因此书被苏联禁止领取诺贝尔奖。", gradient: "from-white via-blue-100 to-red-200" },
  { id: "exp-ru-009", title: "一日长于百年", titleEn: "The Day Lasts More Than a Hundred Years", author: "钦吉斯·艾特玛托夫", country: "苏联（吉尔吉斯）", flag: "🇰🇬", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "魔幻", "社会"], year: 1980, excerpt: "在中亚草原上的一个小火车站——传说与现实、过去与未来在此交汇。艾特玛托夫将中亚民间传说与科幻元素融为一体。", gradient: "from-amber-400 via-brown-300 to-blue-300" },
  { id: "exp-ru-010", title: "伊万·杰尼索维奇的一天", titleEn: "One Day in the Life of Ivan Denisovich", author: "索尔仁尼琴", country: "苏联", flag: "🇷🇺", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1962, excerpt: "斯大林劳改营中一个囚犯的'平常一天'。索尔仁尼琴以最简洁的叙述打开了一座冰山——那冰山下是整个古拉格群岛。", gradient: "from-white via-gray-200 to-black" },
  { id: "exp-ru-011", title: "大师与玛格丽特", titleEn: "The Master and Margarita", author: "米哈伊尔·布尔加科夫", country: "苏联", flag: "🇷🇺", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["魔幻", "哲学", "爱情"], year: 1966, excerpt: "魔鬼沃兰德带着随从来到苏联时期的莫斯科搅得天翻地覆。布尔加科夫的遗作以魔幻笔触将政治讽刺与宗教沉思融为一体——'手稿是烧不掉的。'", gradient: "from-black via-purple-800 to-red-600" },

  // ==================== 欧洲 — 意大利/西班牙/葡萄牙 (40+) ====================

  { id: "exp-it-001", title: "君士坦丁堡的陷落", titleEn: "The Fall of Constantinople", author: "亚历山德罗·曼佐尼", country: "意大利", flag: "🇮🇹", continent: "europe", era: "近代 (1700—1900)", genre: ["诗歌"], themes: ["历史", "宗教"], year: 1822, excerpt: "曼佐尼以宗教颂歌的形式书写了历史事件——在意大利统一运动的前夜，这部作品唤醒了意大利人的民族意识。", gradient: "from-gold-500 via-red-600 to-blue-700" },
  { id: "exp-it-002", title: "豹", titleEn: "The Leopard", author: "朱塞佩·迪·兰佩杜萨", country: "意大利", flag: "🇮🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "哲学"], year: 1958, excerpt: "'如果我们希望一切保持原样，就必须改变一切。'萨利纳亲王在意大利统一运动中目睹旧贵族世界的消逝——一部关于衰败的杰作。", gradient: "from-amber-600 via-gold-500 to-brown-400" },
  { id: "exp-it-003", title: "不存在的骑士", titleEn: "The Nonexistent Knight", author: "伊塔洛·卡尔维诺", country: "意大利", flag: "🇮🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "魔幻"], year: 1959, excerpt: "阿吉鲁尔福爵士——一套完美的白色盔甲——里面没有身体。卡尔维诺以这则哲学寓言完成了'我们的祖先'三部曲。", gradient: "from-white via-gray-200 to-black" },
  { id: "exp-es-001", title: "羊泉村", titleEn: "Fuenteovejuna", author: "洛佩·德·维加", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["戏剧"], themes: ["社会", "历史"], year: 1619, excerpt: "'是谁杀了骑士团长？''是羊泉村！'——所有村民共同承担了杀死暴虐领主的责任。西班牙黄金世纪戏剧中最有力的集体英雄主义宣言。", gradient: "from-red-600 via-gold-400 to-brown-300" },
  { id: "exp-es-002", title: "修道院纪事", titleEn: "Baltasar and Blimunda", author: "若泽·萨拉马戈", country: "葡萄牙", flag: "🇵🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "历史", "魔幻"], year: 1982, excerpt: "十八世纪葡萄牙——国王修建马夫拉修道院，独臂士兵巴尔塔萨尔与'能看到意志'的少女布里蒙达之间的爱情在石头与鲜血中绽放。", gradient: "from-gray-600 via-gold-400 to-red-300" },
  { id: "exp-es-003", title: "时间的针脚", titleEn: "The Time in Between", author: "玛丽亚·杜埃尼亚斯", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "历史", "冒险"], year: 2009, excerpt: "一个西班牙女裁缝在二战期间成为摩洛哥与伊比利亚半岛之间的间谍。杜埃尼亚斯以这部小说重振了西班牙历史小说的传统。", gradient: "from-red-500 via-gold-400 to-blue-300" },

  // ==================== 非洲 (50+) ====================

  { id: "exp-af-001", title: "饥饿之路", titleEn: "The Famished Road", author: "本·奥克里", country: "尼日利亚", flag: "🇳🇬", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["魔幻", "社会", "哲学"], year: 1991, excerpt: "阿扎罗是一个'阿比库'——在灵界与人间之间往返的孩子。奥克里以约鲁巴神话为底色书写了一部非洲版的《百年孤独》。布克奖。", gradient: "from-orange-500 via-green-400 to-blue-300" },
  { id: "exp-af-002", title: "半轮黄日", titleEn: "Half of a Yellow Sun", author: "奇玛曼达·阿迪契", country: "尼日利亚", flag: "🇳🇬", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "爱情", "历史"], year: 2006, excerpt: "比夫拉战争改变了三个人的生活。阿迪契以宏大的叙事将后殖民非洲的创伤书写为令人心碎的个人命运。", gradient: "from-red-600 via-yellow-400 to-green-300" },
  { id: "exp-af-003", title: "等待野蛮人", titleEn: "Waiting for the Barbarians", author: "J.M.库切", country: "南非", flag: "🇿🇦", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1980, excerpt: "帝国边境的一位老法官在'文明'与'野蛮'之间做出了选择。库切以这部寓言小说追问了权力、酷刑与人的尊严。", gradient: "from-gray-500 via-brown-400 to-red-300" },
  { id: "exp-af-004", title: "铁器时代", titleEn: "Age of Iron", author: "J.M.库切", country: "南非", flag: "🇿🇦", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "历史"], year: 1990, excerpt: "一个垂死的古典学教授在种族隔离末期的开普敦给远在美国的女儿写信——库切为南非的'铁器时代'写下了最冰冷的哀歌。", gradient: "from-gray-600 via-black to-red-500" },
  { id: "exp-af-005", title: "我们需要新名字", titleEn: "We Need New Names", author: "诺维奥莱特·布拉瓦约", country: "津巴布韦", flag: "🇿🇼", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 2013, excerpt: "小姑娘达林从津巴布韦贫民窟到美国的移民之旅。布拉瓦约以童真的声音讲述了后殖民非洲的失落与美国梦的幻灭。", gradient: "from-yellow-500 via-green-400 to-blue-300" },

  // ==================== 美洲 — 美国 (70+) ====================

  { id: "exp-am-001", title: "红字", titleEn: "The Scarlet Letter", author: "纳撒尼尔·霍桑", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "宗教", "心理"], year: 1850, excerpt: "清教徒波士顿——海丝特·白兰因通奸罪被迫在胸前佩戴红色的'A'字。霍桑以幽暗的心理深度探索了罪、耻与救赎。", gradient: "from-red-800 via-gray-600 to-black" },
  { id: "exp-am-002", title: "白鲸", titleEn: "Moby-Dick", author: "赫尔曼·梅尔维尔", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["冒险", "哲学", "自然"], year: 1851, excerpt: "(已在核心库中)", gradient: "from-slate-700 via-blue-800 to-cyan-600" },
  { id: "exp-am-003", title: "瓦尔登湖", titleEn: "Walden", author: "亨利·大卫·梭罗", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["自然", "哲学", "社会"], year: 1854, excerpt: "'我到林中去是因为我希望审慎地生活。'梭罗在瓦尔登湖畔独居两年两个月零两天——写下了一部关于简单生活、自然观察与公民不服从的经典。", gradient: "from-green-600 via-blue-400 to-white" },
  { id: "exp-am-004", title: "汤姆叔叔的小屋", titleEn: "Uncle Tom's Cabin", author: "哈丽叶特·比彻·斯托", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "历史"], year: 1852, excerpt: "林肯说：'就是这本小书引发了这场大战。'汤姆叔叔的苦难是美国奴隶制最有力的文学控诉——一本改变了一个国家的书。", gradient: "from-red-700 via-brown-500 to-black" },
  { id: "exp-am-005", title: "小妇人", titleEn: "Little Women", author: "路易莎·梅·奥尔科特", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1868, excerpt: "马奇家四姐妹——梅格、乔、贝丝、艾米——的成长故事。'乔'是无数女性读者心中的文学原型：一个想当作家、拒绝传统婚姻的独立灵魂。", gradient: "from-rose-400 via-pink-300 to-lavender-200" },
  { id: "exp-am-006", title: "觉醒", titleEn: "The Awakening", author: "凯特·肖邦", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["心理", "社会", "爱情"], year: 1899, excerpt: "埃德娜·庞特利尔拒绝再做'贤妻良母'——1899年的这部小说因'不道德'被禁。今天被视为女性主义文学的先驱。", gradient: "from-blue-500 via-teal-400 to-green-300" },
  { id: "exp-am-007", title: "太阳照常升起", titleEn: "The Sun Also Rises", author: "欧内斯特·海明威", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 1926, excerpt: "一战后的'迷惘的一代'在巴黎与潘普洛纳之间徘徊——海明威以'冰山理论'重新定义了英语散文。", gradient: "from-amber-400 via-red-300 to-black" },
  { id: "exp-am-008", title: "我弥留之际", titleEn: "As I Lay Dying", author: "威廉·福克纳", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "社会", "自然"], year: 1930, excerpt: "十五个叙述者、五十九个章节——邦德伦一家运送母亲的遗体穿过密西西比的洪泛区。福克纳说六个星期就写完了，'没有改动一个字'。", gradient: "from-brown-600 via-mud-400 to-green-300" },
  { id: "exp-am-009", title: "愤怒的葡萄", titleEn: "The Grapes of Wrath", author: "约翰·斯坦贝克", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "历史"], year: 1939, excerpt: "乔德一家被沙尘暴和银行从俄克拉荷马驱赶到加利福尼亚——'应许之地'并非天堂。斯坦贝克以这部史诗获普利策奖。", gradient: "from-amber-500 via-brown-400 to-red-300" },
  { id: "exp-am-010", title: "丧钟为谁而鸣", titleEn: "For Whom the Bell Tolls", author: "海明威", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["战争", "爱情", "哲学"], year: 1940, excerpt: "'不要问丧钟为谁而鸣——它就为你而鸣。'西班牙内战的四天三夜中乔丹在炸桥任务与爱情之间的抉择。", gradient: "from-red-700 via-brown-500 to-black" },
  { id: "exp-am-011", title: "推销员之死", titleEn: "Death of a Salesman", author: "阿瑟·米勒", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["戏剧"], themes: ["社会", "心理", "哲学"], year: 1949, excerpt: "威利·洛曼——一个被'美国梦'吞噬的普通人。阿瑟·米勒以这部美国悲剧追问：当一个人不再'有用'时，他还值什么？", gradient: "from-gray-600 via-blue-400 to-red-300" },
  { id: "exp-am-012", title: "欲望号街车", titleEn: "A Streetcar Named Desire", author: "田纳西·威廉斯", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["戏剧"], themes: ["心理", "社会", "爱情"], year: 1947, excerpt: "布兰奇·杜波依斯——'我总是依赖陌生人的善意'——在新奥尔良的妹妹家中遭遇粗野的斯坦利。美国戏剧史上最伟大的角色之一。", gradient: "from-purple-400 via-red-300 to-gray-200" },
  { id: "exp-am-013", title: "在路上", titleEn: "On the Road", author: "杰克·凯鲁亚克", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["冒险", "哲学", "社会"], year: 1957, excerpt: "萨尔·帕拉迪斯与迪安·莫里亚蒂横穿美洲大陆——凯鲁亚克在三周内打完一整卷120英尺打字纸。'垮掉的一代'的圣经。", gradient: "from-blue-600 via-white-300 to-red-400" },
  { id: "exp-am-014", title: "第22条军规", titleEn: "Catch-22", author: "约瑟夫·海勒", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "哲学"], year: 1961, excerpt: "如果你疯了就可以免于飞行，但如果你申请免于飞行就证明你没疯——'第22条军规'。海勒以黑色幽默将战争的荒谬写成了文学经典。", gradient: "from-green-600 via-khaki-400 to-red-300" },
  { id: "exp-am-015", title: "五号屠场", titleEn: "Slaughterhouse-Five", author: "库尔特·冯内古特", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "哲学", "魔幻"], year: 1969, excerpt: "比利·皮尔格林在时间中'脱臼'——从德累斯顿轰炸的火海滑向外星动物园。冯内古特以科幻外壳写出了一部反战经典。", gradient: "from-orange-500 via-red-400 to-blue-300" },
  { id: "exp-am-016", title: "紫色", titleEn: "The Color Purple", author: "艾丽丝·沃克", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "爱情", "心理"], year: 1982, excerpt: "以书信体写成——黑人女性西莉写给上帝的信——从被虐待的沉默到自我赋权的发声。普利策奖。", gradient: "from-purple-600 via-rose-500 to-pink-400" },

  // ==================== 美洲 — 拉丁美洲 (50+) ====================

  { id: "exp-la-001", title: "这个世界的王国", titleEn: "The Kingdom of This World", author: "阿莱霍·卡彭铁尔", country: "古巴", flag: "🇨🇺", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "魔幻", "社会"], year: 1949, excerpt: "以海地革命为背景——卡彭铁尔在序言中首次提出'神奇的现实'的概念。拉丁美洲本身就是一个神奇现实的大陆。", gradient: "from-green-600 via-blue-500 to-red-400" },
  { id: "exp-la-002", title: "绿房子", titleEn: "The Green House", author: "马里奥·巴尔加斯·略萨", country: "秘鲁", flag: "🇵🇪", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 1966, excerpt: "略萨以多重叙事时间和视角的拼接讲述秘鲁沙漠边缘一座妓院'绿房子'的故事——'总体小说'的叙事实验。", gradient: "from-green-500 via-amber-400 to-red-300" },
  { id: "exp-la-003", title: "一桩事先张扬的凶杀案", titleEn: "Chronicle of a Death Foretold", author: "加西亚·马尔克斯", country: "哥伦比亚", flag: "🇨🇴", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "魔幻"], year: 1981, excerpt: "圣地亚哥·纳萨尔将在早晨被杀——整个镇子都知道却无人阻止。马尔克斯以侦探小说的形式追问：一群人如何'共同'犯下一桩谋杀？", gradient: "from-red-600 via-white-300 to-blue-400" },
  { id: "exp-la-004", title: "族长的秋天", titleEn: "The Autumn of the Patriarch", author: "加西亚·马尔克斯", country: "哥伦比亚", flag: "🇨🇴", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "魔幻"], year: 1975, excerpt: "一个统治了不知多少年的独裁者——每一页都是句子洪流。马尔克斯以诗的密度书写了权力的孤独。", gradient: "from-amber-700 via-brown-500 to-black" },
  { id: "exp-la-005", title: "2666", titleEn: "2666", author: "罗贝托·波拉尼奥", country: "智利/墨西哥", flag: "🇨🇱", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 2004, excerpt: "波拉尼奥的遗作——五部分构成的巨制，核心是墨西哥边境城市中数百名女性被谋杀的骇人现实。一部二十世纪的'文学黑洞'。", gradient: "from-black via-gray-700 to-red-600" },
  { id: "exp-la-006", title: "蜘蛛女之吻", titleEn: "Kiss of the Spider Woman", author: "曼努埃尔·普伊格", country: "阿根廷", flag: "🇦🇷", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1976, excerpt: "监狱牢房里，一个同性恋者向一个革命者讲述老电影——全对话体书写。在两个囚徒之间，一种不可能的温情悄然生长。", gradient: "from-red-500 via-purple-400 to-blue-300" },

  // ==================== 美洲 — 加拿大 (20+) ====================

  { id: "exp-ca-001", title: "使女的故事", titleEn: "The Handmaid's Tale", author: "玛格丽特·阿特伍德", country: "加拿大", flag: "🇨🇦", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "哲学", "心理"], year: 1985, excerpt: "在神权男性极权国家基列共和国——女性被简化为生育工具。阿特伍德说这本书中发生的每一件事都曾在人类历史上的某个时刻真实发生过。", gradient: "from-red-700 via-white-200 to-black" },
  { id: "exp-ca-002", title: "盲刺客", titleEn: "The Blind Assassin", author: "玛格丽特·阿特伍德", country: "加拿大", flag: "🇨🇦", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 2000, excerpt: "艾丽丝·蔡斯晚年回忆录揭开了妹妹劳拉之死的谜团——小说中嵌套另一部小说，小说中又有小说。布克奖。", gradient: "from-gray-600 via-red-400 to-black" },
  { id: "exp-ca-003", title: "英国病人", titleEn: "The English Patient", author: "迈克尔·翁达杰", country: "加拿大", flag: "🇨🇦", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "战争", "心理"], year: 1992, excerpt: "二战末期四个受伤的人在意大利一座废弃别墅中相遇。翁达杰以诗歌般的散文书写跨越国界的爱、身份与记忆。布克奖。", gradient: "from-amber-500 via-desert-300 to-blue-200" },

  // ==================== 大洋洲 (30+) ====================

  { id: "exp-oc-001", title: "荆棘鸟", titleEn: "The Thorn Birds", author: "科琳·麦卡洛", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "历史", "心理"], year: 1977, excerpt: "梅吉与神父拉尔夫的禁忌之恋横跨澳大利亚三代人。'荆棘鸟一生只歌唱一次——当它把胸膛刺入最尖的荆棘时。'", gradient: "from-red-600 via-amber-500 to-brown-400" },
  { id: "exp-oc-002", title: "吉米·布莱克史密斯的圣歌", titleEn: "The Chant of Jimmie Blacksmith", author: "托马斯·基尼利", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1972, excerpt: "以1900年一个混血原住民青年杀害白人妇女的真实事件为素材——基尼利追问：当一个被系统性剥夺尊严的人，暴力是唯一的回答吗？", gradient: "from-red-700 via-brown-500 to-black" },
  { id: "exp-oc-003", title: "辛德勒的方舟", titleEn: "Schindler's Ark", author: "托马斯·基尼利", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "战争", "社会"], year: 1982, excerpt: "一个纳粹党员、投机商人奥斯卡·辛德勒如何在二战中救了1100名犹太人。布克奖——斯皮尔伯格据此拍摄《辛德勒的名单》。", gradient: "from-red-800 via-black to-white" },
  { id: "exp-oc-004", title: "神秘的河流", titleEn: "The Secret River", author: "凯特·格伦维尔", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "自然"], year: 2005, excerpt: "十九世纪初一个被流放到澳大利亚的英国罪犯试图在霍克斯伯里河畔建立新生活——但这片土地属于原住民。'定居'与'入侵'是同一件事的两面。", gradient: "from-blue-600 via-green-500 to-brown-400" },
  { id: "exp-oc-005", title: "云街", titleEn: "Cloudstreet", author: "蒂姆·温顿", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "魔幻", "心理"], year: 1991, excerpt: "两个家庭在珀斯同一座大房子里的二十年。温顿将澳洲最普通的日常生活赋予了史诗的质感——澳洲魔幻现实主义的杰作。", gradient: "from-blue-400 via-white-200 to-amber-300" },
  { id: "exp-oc-006", title: "骑鲸人", titleEn: "The Whale Rider", author: "威提·依希马埃拉", country: "新西兰", flag: "🇳🇿", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "自然", "魔幻"], year: 1987, excerpt: "毛利族女孩卡胡从出生就被酋长祖父忽视——因为她是女孩。但古老的鲸鱼听见了她的呼唤——关于性别、传统与自然之灵的小说。", gradient: "from-blue-600 via-teal-500 to-white" },
  { id: "exp-oc-007", title: "偷书贼", titleEn: "The Book Thief", author: "马克斯·苏萨克", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "社会", "心理"], year: 2005, excerpt: "死神作为叙述者——纳粹德国，一个小女孩莉赛尔偷了一本又一本的书。'这是关于一个被文字喂养的灵魂的故事。'", gradient: "from-gray-700 via-red-500 to-white" },

  // ==================== 诺贝尔文学奖得主补充 (50+) ====================

  { id: "exp-nb-001", title: "荒原", titleEn: "The Waste Land", author: "T.S.艾略特", country: "英国/美国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["诗歌"], themes: ["哲学", "宗教", "社会"], year: 1922, excerpt: "'四月是最残忍的月份。'艾略特以这部四百多行的长诗为现代文明的'精神废墟'写下了最权威的诗篇。诺贝尔奖1948。", gradient: "from-brown-600 via-gray-400 to-black" },
  { id: "exp-nb-002", title: "德里纳河上的桥", titleEn: "The Bridge on the Drina", author: "伊沃·安德里奇", country: "塞尔维亚", flag: "🇷🇸", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["历史", "社会"], year: 1945, excerpt: "一座桥连接了东西方——安德里奇以维谢格勒的德里纳河桥为沉默叙述者跨越四个世纪的巴尔干历史。诺贝尔奖1961。", gradient: "from-stone-500 via-amber-400 to-blue-300" },
  { id: "exp-nb-003", title: "长路将尽", titleEn: "Long Day's Journey into Night", author: "尤金·奥尼尔", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["戏剧"], themes: ["心理", "社会", "哲学"], year: 1956, excerpt: "蒂龙一家在康涅狄格避暑别墅中的一天——奥尼尔以自身家庭为蓝本将毒瘾、疾病与相互折磨书写为美国戏剧史上最伟大的悲剧。", gradient: "from-gray-700 via-blue-500 to-black" },
  { id: "exp-nb-004", title: "克里斯汀·拉夫朗的女儿", titleEn: "Kristin Lavransdatter", author: "西格丽德·温塞特", country: "挪威", flag: "🇳🇴", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "宗教", "历史"], year: 1922, excerpt: "十四世纪挪威——克里斯汀的一生从少女到老妇。温塞特以这部中世纪三部曲获得了诺贝尔奖——一部北欧版《战争与和平》。", gradient: "from-white via-blue-200 to-green-300" },
  { id: "exp-nb-005", title: "走出非洲", titleEn: "Out of Africa", author: "伊萨克·迪内森", country: "丹麦", flag: "🇩🇰", continent: "europe", era: "现代 (1900—1950)", genre: ["散文/随笔"], themes: ["自然", "社会", "心理"], year: 1937, excerpt: "'我在非洲有一座农场。'迪内森以优雅而哀伤的笔触回忆了在肯尼亚的十七年。海明威说她应该获得诺贝尔奖。", gradient: "from-amber-500 via-red-400 to-green-300" },
  { id: "exp-nb-006", title: "蝇王", titleEn: "Lord of the Flies", author: "威廉·戈尔丁", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会", "哲学"], year: 1954, excerpt: "一群流落荒岛的英国学童从文明倒退回野蛮。戈尔丁说：'人制造恶就像蜜蜂制造蜂蜜。'一部关于人性之暗的不朽寓言。诺贝尔奖1983。", gradient: "from-green-700 via-jungle-500 to-black" },
  { id: "exp-nb-007", title: "金色笔记", titleEn: "The Golden Notebook", author: "多丽丝·莱辛", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会", "爱情"], year: 1962, excerpt: "安娜·伍尔夫的四本笔记——黑色、红色、黄色、蓝色——记录了她作为作家、共产主义者、恋人和日记作者的不同自我。诺贝尔奖2007。", gradient: "from-black via-red-500 to-gold-400" },
  { id: "exp-nb-008", title: "海浪", titleEn: "The Waves", author: "弗吉尼亚·伍尔夫", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学", "自然"], year: 1931, excerpt: "六个人物从童年到老年的内心独白以海浪的节奏穿插其间。伍尔夫最实验性的作品——'不是小说不是诗，而是一种从未有人尝试过的东西。'", gradient: "from-blue-300 via-white-200 to-teal-200" },

  // ==================== 第三批: 全球文学补充 (350+) ====================

  // --- 中国文学续 (40+) ---
  { id: "x3-ch-001", title: "唐宋传奇集", titleEn: "Tang and Song Dynasty Tales", author: "鲁迅编", country: "中国", flag: "🇨🇳", continent: "asia", era: "中世纪 (500—1500)", genre: ["民间故事"], themes: ["爱情", "魔幻", "社会"], year: 1927, excerpt: "鲁迅辑录的唐宋传奇选集。《霍小玉传》《李娃传》《莺莺传》——中国文言短篇小说第一个黄金时代的精华。", gradient: "from-amber-500 via-red-400 to-purple-300" },
  { id: "x3-ch-002", title: "元曲选", titleEn: "Selected Yuan Dynasty Operas", author: "臧懋循编", country: "中国", flag: "🇨🇳", continent: "asia", era: "中世纪 (500—1500)", genre: ["戏剧"], themes: ["爱情", "社会", "历史"], year: 1616, excerpt: "收录百种元人杂剧的权威选本。《窦娥冤》《汉宫秋》《梧桐雨》——元代是中国戏剧的第一个高峰。", gradient: "from-red-600 via-gold-400 to-purple-300" },
  { id: "x3-ch-003", title: "万历十五年", titleEn: "1587: A Year of No Significance", author: "黄仁宇", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "社会"], year: 1981, excerpt: "以1587年——一个看似平淡无奇的年份——切入晚明帝国运作的深层逻辑。黄仁宇开创的'大历史'不只讲历史，更是文学。", gradient: "from-amber-500 via-brown-400 to-gray-300" },
  { id: "x3-ch-004", title: "务虚笔记", titleEn: "Notes on Principles", author: "史铁生", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "爱情"], year: 1996, excerpt: "一个坐在轮椅上的人对爱、命运与存在的沉思。史铁生以这部哲思小说将中国当代文学推向了最深邃的精神高度。", gradient: "from-gray-600 via-blue-400 to-white" },
  { id: "x3-ch-005", title: "许三观卖血记", titleEn: "Chronicle of a Blood Merchant", author: "余华", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1995, excerpt: "许三观一生卖了十一次血——每一次都是家庭遭遇危机之时。余华以极简的语言为底层中国人的生存韧性写下了最震撼的文学证词。", gradient: "from-red-700 via-white-300 to-black" },
  { id: "x3-ch-006", title: "檀香刑", titleEn: "Sandalwood Death", author: "莫言", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "心理"], year: 2001, excerpt: "以清末山东为背景——一种残酷的刑罚'檀香刑'贯穿全书。莫言将民间戏曲'猫腔'的节奏注入小说，为权力与暴力写下最令人不安的叙事。", gradient: "from-red-900 via-brown-600 to-black" },
  { id: "x3-ch-007", title: "繁花", titleEn: "Blossoms", author: "金宇澄", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "爱情"], year: 2013, excerpt: "上海六十年代到九十年代——以沪语思维和密集对话写成的城市史诗。茅盾文学奖——一座'文学博物馆'收藏了上海的市井灵魂。", gradient: "from-rose-400 via-gold-300 to-white" },
  { id: "x3-ch-008", title: "三体", titleEn: "The Three-Body Problem", author: "刘慈欣", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "社会", "冒险"], year: 2008, excerpt: "文化大革命中一个天体物理学家向宇宙发出了信号——四光年外的'三体文明'正在前来。中国科幻文学走向世界的里程碑。雨果奖。", gradient: "from-black via-blue-900 to-purple-700" },

  // --- 日本文学续 (30+) ---
  { id: "x3-jp-001", title: "天平之甍", titleEn: "The Roof Tile of Tempyo", author: "井上靖", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "宗教", "冒险"], year: 1957, excerpt: "鉴真和尚六次东渡日本的故事。井上靖以中国唐代为舞台写出了一部关于信念与文化交流的宏大历史小说。", gradient: "from-amber-400 via-gold-300 to-teal-400" },
  { id: "x3-jp-002", title: "敦煌", titleEn: "Tun-huang", author: "井上靖", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "冒险"], year: 1959, excerpt: "北宋书生赵行德在敦煌的传奇经历——井上靖以西域为舞台书写了一部关于文明保存的壮丽史诗。", gradient: "from-amber-500 via-desert-300 to-blue-400" },
  { id: "x3-jp-003", title: "古都", titleEn: "The Old Capital", author: "川端康成", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "自然", "社会"], year: 1962, excerpt: "京都——一对自幼分离的双胞胎姐妹千重子和苗子的故事。川端以京都的四季风物为背景写了一曲关于身份与归属的哀歌。", gradient: "from-pink-300 via-white-200 to-green-200" },
  { id: "x3-jp-004", title: "听风的歌", titleEn: "Hear the Wind Sing", author: "村上春树", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "爱情"], year: 1979, excerpt: "村上春树的处女作——'我'与'老鼠'在神户的夏天。村上式'轻薄'但深沉的叙事语调在此诞生。", gradient: "from-blue-300 via-white-200 to-amber-200" },
  { id: "x3-jp-005", title: "箱男", titleEn: "The Box Man", author: "安部公房", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1973, excerpt: "一个男人决定放弃正常生活住进一个纸箱——安部公房以这个极端的设定追问了现代都市中'存在'的本质。", gradient: "from-gray-500 via-brown-400 to-black" },

  // --- 韩国文学续 (25+) ---
  { id: "x3-kr-001", title: "闲山岛", titleEn: "Hansan Island", author: "金薰", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "战争"], year: 2001, excerpt: "以李舜臣和壬辰倭乱为背景的历史小说——金薰以极简的笔法重述了朝鲜历史上最著名的海战英雄。", gradient: "from-blue-600 via-white-200 to-red-400" },
  { id: "x3-kr-002", title: "诗人", titleEn: "The Poet", author: "李承雨", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会"], year: 1992, excerpt: "以韩国最著名的流浪诗人金笠为原型——一个诗人在朝鲜王朝末期的漂泊与抗争。", gradient: "from-gray-500 via-white-200 to-black" },
  { id: "x3-kr-003", title: "少年来了", titleEn: "Human Acts", author: "韩江", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "心理"], year: 2014, excerpt: "以1980年光州事件为背景——韩江以不同人物的视角拼贴出民主化运动的创伤记忆。诺贝尔文学奖。", gradient: "from-red-600 via-white-300 to-blue-500" },

  // --- 东南亚文学续 (25+) ---
  { id: "x3-sea-001", title: "沈默的暴动", titleEn: "This Earth of Mankind", author: "普拉姆迪亚", country: "印度尼西亚", flag: "🇮🇩", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 1980, excerpt: "普拉姆迪亚的'布鲁岛四部曲'之首。以殖民时期爪哇为背景——印尼民族意识的觉醒在跨种族的爱情中得到了最动人的表达。", gradient: "from-red-600 via-white-300 to-green-500" },
  { id: "x3-sea-002", title: "斗争", titleEn: "Child of All Nations", author: "普拉姆迪亚", country: "印度尼西亚", flag: "🇮🇩", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会"], year: 1980, excerpt: "布鲁岛四部曲之二。明克的故事继续——印尼民族运动在与殖民主义的斗争中步步推进。", gradient: "from-red-700 via-gold-500 to-black" },

  // --- 英国文学续 (40+) ---
  { id: "x3-uk-001", title: "劝导", titleEn: "Persuasion", author: "简·奥斯汀", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1817, excerpt: "安妮·艾略特——奥斯汀笔下最年长也最成熟的女主角——二十七岁时与八年前被她'劝导'拒绝的温特沃斯上校重逢。奥斯汀的最后一部小说，也是她最深沉的一部。", gradient: "from-blue-300 via-white-200 to-rose-200" },
  { id: "x3-uk-002", title: "名利场", titleEn: "Vanity Fair", author: "威廉·萨克雷", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "心理"], year: 1848, excerpt: "'一部没有英雄的小说'——蓓基·夏泼是文学史上最迷人的'恶女'之一。萨克雷以这部讽刺巨著为英国摄政时代画了一幅最不留情面的肖像。", gradient: "from-amber-400 via-gold-300 to-yellow-200" },
  { id: "x3-uk-003", title: "米德尔马契", titleEn: "Middlemarch", author: "乔治·艾略特", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情", "哲学"], year: 1871, excerpt: "(已在核心库中)", gradient: "from-amber-600 via-yellow-500 to-green-500" },
  { id: "x3-uk-004", title: "儿子与情人", titleEn: "Sons and Lovers", author: "D.H.劳伦斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1913, excerpt: "以矿工家庭的母子关系为切入点——劳伦斯以前所未有的坦率探测了性、情感与工业文明之间的黑暗地带。", gradient: "from-coal-800 via-amber-600 to-red-500" },
  { id: "x3-uk-005", title: "美丽新世界", titleEn: "Brave New World", author: "奥尔德斯·赫胥黎", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "社会"], year: 1932, excerpt: "'人人属于每一个人。'赫胥黎的'快乐'反乌托邦——不再需要暴力来奴役人，只要用基因工程和精神麻醉剂让他们'自愿'地热爱自己的奴役。", gradient: "from-gray-600 via-silver-400 to-blue-300" },
  { id: "x3-uk-006", title: "赎罪", titleEn: "Atonement", author: "伊恩·麦克尤恩", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "战争", "心理"], year: 2001, excerpt: "一个十三岁女孩的错误指控毁掉了两个人的一生。麦克尤恩以多层叙事追问：小说能成为对现实中所犯之罪的'赎罪'吗？", gradient: "from-green-500 via-blue-400 to-rose-300" },
  { id: "x3-uk-007", title: "千万别让我走", titleEn: "Never Let Me Go", author: "石黑一雄", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 2005, excerpt: "黑尔舍姆寄宿学校的三个学生——凯西、汤米和露丝——有着不可告人的命运。石黑以最克制的叙述包裹了最令人心碎的反乌托邦。", gradient: "from-green-400 via-white-200 to-gray-300" },

  // --- 法国文学续 (30+) ---
  { id: "x3-fr-001", title: "萌芽", titleEn: "Germinal", author: "埃米尔·左拉", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "历史"], year: 1885, excerpt: "左拉《卢贡-马卡尔家族》的第十三部——世界文学中最具震撼力的矿井叙事。矿工在黑暗中挖掘，'萌芽'在土壤下生长——革命的力量在地下孕育。", gradient: "from-black via-gray-800 to-red-600" },
  { id: "x3-fr-002", title: "追忆逝水年华·在少女花影下", titleEn: "Within a Budding Grove", author: "普鲁斯特", country: "法国", flag: "🇫🇷", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "爱情", "自然"], year: 1919, excerpt: "《追忆似水年华》第二卷。巴尔贝克的海滩、少女们的身影、第一次的心动——普鲁斯特获得龚古尔奖的正是这一卷。", gradient: "from-blue-300 via-white-200 to-rose-200" },
  { id: "x3-fr-003", title: "恶心", titleEn: "Nausea", author: "让-保罗·萨特", country: "法国", flag: "🇫🇷", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "心理"], year: 1938, excerpt: "安东尼·罗康坦在某一天突然被'恶心'击中——这个世界'太多'了，事物的纯粹存在令人晕眩。存在主义最著名的文学宣言。", gradient: "from-yellow-400 via-brown-300 to-gray-200" },
  { id: "x3-fr-004", title: "林中阳台", titleEn: "A Balcony in the Forest", author: "朱利安·格拉克", country: "法国", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "自然", "心理"], year: 1958, excerpt: "1940年'假战'期间的阿登森林——一个法军中尉在地堡中的等待。格拉克以超现实主义的笔触书写了战争中最奇异的静默。", gradient: "from-green-700 via-gray-500 to-black" },
  { id: "x3-fr-005", title: "情人(剧本)", titleEn: "Hiroshima mon amour", author: "玛格丽特·杜拉斯", country: "法国", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["戏剧"], themes: ["爱情", "战争", "心理"], year: 1960, excerpt: "广岛——一个法国女演员与一个日本建筑师的一夜。杜拉斯以反复、回旋的散文为不可言说的创伤找到了文学的形式。", gradient: "from-black via-red-600 to-white" },

  // --- 德国文学续 (25+) ---
  { id: "x3-de-001", title: "少年维特的烦恼", titleEn: "The Sorrows of Young Werther", author: "歌德", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理", "哲学"], year: 1774, excerpt: "一封封书信中维特的爱恋走向不可挽回的终点。这本书掀起了欧洲的'维特热'——青年们穿着维特的蓝外套黄马甲，有的甚至效仿了维特的结局。", gradient: "from-blue-500 via-yellow-400 to-green-300" },
  { id: "x3-de-002", title: "荒原狼", titleEn: "Steppenwolf", author: "赫尔曼·黑塞", country: "德国", flag: "🇩🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学"], year: 1927, excerpt: "哈里·哈勒尔——一头误入现代文明的'荒原狼'——在市民性与野性之间痛苦分裂。黑塞写尽了现代知识分子的精神困境。", gradient: "from-gray-700 via-slate-500 to-indigo-400" },
  { id: "x3-de-003", title: "玻璃球游戏", titleEn: "The Glass Bead Game", author: "赫尔曼·黑塞", country: "德国", flag: "🇩🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "宗教", "心理"], year: 1943, excerpt: "黑塞获诺贝尔奖的收官之作。在一个虚构的未来精英'卡斯塔里亚省'中学者们以'玻璃球游戏'连接一切人类知识——但克乃西特大师最终选择离开象牙塔。", gradient: "from-teal-500 via-glass-300 to-purple-300" },
  { id: "x3-de-004", title: "朗读者", titleEn: "The Reader", author: "本哈德·施林克", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "历史", "心理"], year: 1995, excerpt: "十五岁的少年与三十六岁的电车售票员汉娜的夏日之恋多年后在法庭上重逢——汉娜作为纳粹战犯受审。关于罪与耻、爱与罚的深刻沉思。", gradient: "from-green-500 via-blue-400 to-gray-300" },

  // --- 俄国文学续 (30+) ---
  { id: "x3-ru-001", title: "上尉的女儿", titleEn: "The Captain's Daughter", author: "普希金", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "历史", "冒险"], year: 1836, excerpt: "以普加乔夫起义为背景的历史小说。年轻的贵族军官与上尉的女儿玛莎在暴乱中的爱情——普希金的最后一部散文作品。", gradient: "from-red-600 via-white-200 to-blue-500" },
  { id: "x3-ru-002", title: "猎人笔记", titleEn: "A Sportsman's Sketches", author: "屠格涅夫", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["社会", "自然"], year: 1852, excerpt: "屠格涅夫以猎人的视角描绘俄罗斯乡村风景与农民生活——这部短篇集直接推动了亚历山大二世废除农奴制的决定。", gradient: "from-green-500 via-brown-300 to-amber-200" },
  { id: "x3-ru-003", title: "被欺凌与被侮辱的", titleEn: "The Insulted and Humiliated", author: "陀思妥耶夫斯基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 1861, excerpt: "陀思妥耶夫斯基流放归来后的第一部长篇。在彼得堡的下层社会——被欺凌与被侮辱的人们如何在绝望中保持尊严。", gradient: "from-gray-600 via-blue-400 to-red-300" },
  { id: "x3-ru-004", title: "三姊妹", titleEn: "Three Sisters", author: "安东·契诃夫", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["戏剧"], themes: ["社会", "心理"], year: 1901, excerpt: "奥尔加、玛莎、伊琳娜——三个受过教育的女性被困在外省小城，年复一年地梦想着'去莫斯科！'契诃夫最令人心碎的'喜剧'。", gradient: "from-gray-400 via-blue-200 to-white" },

  // --- 意大利/西班牙文学续 (25+) ---
  { id: "x3-it-001", title: "木偶奇遇记", titleEn: "The Adventures of Pinocchio", author: "卡洛·科洛迪", country: "意大利", flag: "🇮🇹", continent: "europe", era: "近代 (1700—1900)", genre: ["民间故事"], themes: ["冒险", "哲学"], year: 1883, excerpt: "老木匠杰佩托用一块会说话的木头雕出了一个小木偶——匹诺曹。每一次说谎鼻子就会变长。意大利在世界文学中最著名的贡献之一。", gradient: "from-red-400 via-amber-300 to-brown-200" },
  { id: "x3-it-002", title: "六个寻找作者的剧中人", titleEn: "Six Characters in Search of an Author", author: "路易吉·皮兰德娄", country: "意大利", flag: "🇮🇹", continent: "europe", era: "现代 (1900—1950)", genre: ["戏剧"], themes: ["哲学", "心理"], year: 1921, excerpt: "排练中的剧团被六个'角色'闯入——他们被作者创造后抛弃，现在要求一个舞台。皮兰德娄以元戏剧颠覆了现实与虚构的边界。诺贝尔奖。", gradient: "from-gray-500 via-white-200 to-black" },
  { id: "x3-es-001", title: "风之影", titleEn: "The Shadow of the Wind", author: "卡洛斯·鲁伊斯·萨丰", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["冒险", "爱情", "魔幻"], year: 2001, excerpt: "1945年巴塞罗那——一个小男孩在'遗忘书之墓'中找到了一本名为《风之影》的书，从此被卷入了一个跨越数十年的谜团。献给爱书人的小说。", gradient: "from-blue-800 via-purple-700 to-red-600" },

  // --- 北欧文学续 (20+) ---
  { id: "x3-nord-001", title: "培尔·金特", titleEn: "Peer Gynt", author: "易卜生", country: "挪威", flag: "🇳🇴", continent: "europe", era: "近代 (1700—1900)", genre: ["戏剧"], themes: ["冒险", "心理", "哲学"], year: 1867, excerpt: "培尔·金特——一个永远在逃避'自我'的浪子——从挪威山谷到摩洛哥沙漠再到疯人院。他最终要面对：你这一生到底成为过你自己吗？", gradient: "from-green-600 via-snow-200 to-blue-400" },
  { id: "x3-nord-002", title: "饥饿", titleEn: "Hunger", author: "克努特·汉姆生", country: "挪威", flag: "🇳🇴", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["心理", "社会"], year: 1890, excerpt: "一个匿名的年轻作家在克里斯蒂安尼亚的饥饿边缘挣扎。汉姆生以第一人称意识流（早于乔伊斯三十年）将饥饿如何扭曲人心智写得入骨。", gradient: "from-gray-500 via-amber-300 to-red-200" },
  { id: "x3-nord-003", title: "尼尔斯骑鹅旅行记", titleEn: "The Wonderful Adventures of Nils", author: "塞尔玛·拉格洛夫", country: "瑞典", flag: "🇸🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["民间故事"], themes: ["冒险", "自然", "社会"], year: 1907, excerpt: "首位女性诺贝尔文学奖得主最著名的作品。被惩罚变小了的尼尔斯骑着鹅飞越瑞典——一部写给儿童的地理与德育童话。", gradient: "from-blue-400 via-green-300 to-white" },
  { id: "x3-nord-004", title: "长袜子皮皮", titleEn: "Pippi Longstocking", author: "阿斯特丽德·林格伦", country: "瑞典", flag: "🇸🇪", continent: "europe", era: "当代 (1950—)", genre: ["民间故事"], themes: ["冒险", "社会"], year: 1945, excerpt: "一个九岁女孩、一匹马、一只猴子、一整箱金币——皮皮以她的超人之力颠覆了成人世界的所有规则。", gradient: "from-red-500 via-orange-400 to-yellow-300" },

  // --- 东欧文学续 (25+) ---
  { id: "x3-ee-001", title: "好兵帅克", titleEn: "The Good Soldier Svejk", author: "雅罗斯拉夫·哈谢克", country: "捷克", flag: "🇨🇿", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["战争", "社会"], year: 1923, excerpt: "帅克——一个看似白痴的捷克士兵——以'绝对服从'将奥匈帝国的军事官僚体制变成了全欧洲最庞大的笑话机器。", gradient: "from-green-500 via-gold-400 to-red-300" },
  { id: "x3-ee-002", title: "玩笑", titleEn: "The Joke", author: "米兰·昆德拉", country: "捷克", flag: "🇨🇿", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 1967, excerpt: "一张明信片上的玩笑话毁了一个人的一生。昆德拉以多人称叙述拼接出斯大林时代捷克社会的'残酷笑话'。", gradient: "from-gray-600 via-red-400 to-black" },
  { id: "x3-ee-003", title: "索拉里斯星", titleEn: "Solaris", author: "斯坦尼斯瓦夫·莱姆", country: "波兰", flag: "🇵🇱", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理"], year: 1961, excerpt: "索拉里斯星的海洋是一个有意识的存在——它从宇航员的记忆中'制造'出他们最深的愧疚。莱姆以科幻为壳追问：人类真的有能力理解非人类的智慧吗？", gradient: "from-blue-900 via-ocean-500 to-white" },

  // --- 非洲文学续 (30+) ---
  { id: "x3-af-001", title: "阿凯：我的童年", titleEn: "Ake: The Years of Childhood", author: "沃莱·索因卡", country: "尼日利亚", flag: "🇳🇬", continent: "africa", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["社会", "历史"], year: 1981, excerpt: "索因卡以诗意笔触回忆在尼日利亚阿凯度过的童年。一个非洲男孩的成长故事中流淌着约鲁巴文化的色彩与气味。诺贝尔奖得主的童年自传。", gradient: "from-green-600 via-yellow-400 to-amber-300" },
  { id: "x3-af-002", title: "黑人的灵魂", titleEn: "The Souls of Black Folk", author: "W.E.B.杜波依斯", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["社会", "哲学", "心理"], year: 1903, excerpt: "'二十世纪的问题就是肤色界线的问题。'杜波依斯以'双重意识'的概念开创了非裔美国思想的新纪元。", gradient: "from-black via-red-700 to-green-500" },
  { id: "x3-af-003", title: "撒哈拉的故事", titleEn: "Stories of the Sahara", author: "三毛", country: "中国（写西撒哈拉）", flag: "🇪🇭", continent: "africa", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["爱情", "冒险", "自然"], year: 1976, excerpt: "三毛与荷西在西撒哈拉的沙漠生活。华语世界影响最深远的旅行文学——沙漠中的爱情与冒险。", gradient: "from-amber-400 via-sand-300 to-orange-200" },
  { id: "x3-af-004", title: "返乡", titleEn: "The Return", author: "希沙姆·马塔尔", country: "利比亚", flag: "🇱🇾", continent: "africa", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "社会", "心理"], year: 2016, excerpt: "马塔尔回到卡扎菲倒台后的利比亚寻找三十年前被绑走的父亲的下落。普利策奖——一部关于家园与流亡的杰作。", gradient: "from-amber-500 via-blue-400 to-black" },

  // --- 美洲文学续 (40+) ---
  { id: "x3-am-001", title: "嘉莉妹妹", titleEn: "Sister Carrie", author: "西奥多·德莱塞", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情", "心理"], year: 1900, excerpt: "一个乡村女孩在芝加哥和纽约的上升之路——德莱塞以'不道德'的结局震惊了同时代人：嘉莉没有受到惩罚。美国自然主义文学的开山之作。", gradient: "from-amber-400 via-gray-300 to-blue-200" },
  { id: "x3-am-002", title: "天使望故乡", titleEn: "Look Homeward, Angel", author: "托马斯·沃尔夫", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "社会"], year: 1929, excerpt: "尤金·甘特在南方的童年与少年——沃尔夫以奔腾喷涌的语言写出的自传体小说。威廉·福克纳称他为同时代最伟大的作家。", gradient: "from-amber-500 via-red-400 to-blue-300" },
  { id: "x3-am-003", title: "巴比特", titleEn: "Babbitt", author: "辛克莱·刘易斯", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理"], year: 1922, excerpt: "乔治·巴比特——美国中产阶级'市侩'的原型。刘易斯凭借对美国社会的锋利讽刺获得诺贝尔文学奖——第一个获该奖的美国人。", gradient: "from-gray-500 via-blue-300 to-red-200" },
  { id: "x3-am-004", title: "玻璃动物园", titleEn: "The Glass Menagerie", author: "田纳西·威廉斯", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["戏剧"], themes: ["心理", "社会", "爱情"], year: 1944, excerpt: "汤姆·温菲尔德以'记忆剧'的形式回溯与母亲阿曼达和残疾妹妹劳拉的生活——脆弱的玻璃独角兽就是劳拉的灵魂。", gradient: "from-blue-300 via-white-200 to-pink-200" },
  { id: "x3-am-005", title: "芒果街上的小屋", titleEn: "The House on Mango Street", author: "桑德拉·希斯内罗丝", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 1984, excerpt: "埃斯佩朗莎在芝加哥拉丁裔社区中的成长——四十四段散文诗般的短章编织出一个关于'家'的梦想。", gradient: "from-amber-400 via-red-300 to-teal-300" },
  { id: "x3-am-006", title: "所罗门之歌", titleEn: "Song of Solomon", author: "托妮·莫里森", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "心理", "魔幻"], year: 1977, excerpt: "奶娃·戴德——一个非裔美国青年从密歇根到弗吉尼亚的追寻家族根源之旅。莫里森以这部小说打通了当代与非洲祖先之间的神话通道。", gradient: "from-gold-500 via-green-400 to-black" },
  { id: "x3-am-007", title: "赫索格", titleEn: "Herzog", author: "索尔·贝娄", country: "美国", flag: "🇺🇸", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "哲学", "社会"], year: 1964, excerpt: "摩西·赫索格——一个精神濒临崩溃的知识分子——给活人、死人和上帝写信。贝娄为美国知识分子的精神危机写下了最深刻的小说。", gradient: "from-gray-500 via-blue-400 to-white" },
  { id: "x3-am-008", title: "红色英勇勋章", titleEn: "The Red Badge of Courage", author: "斯蒂芬·克莱恩", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["战争", "心理"], year: 1895, excerpt: "美国内战中一个年轻士兵的心理全景——克莱恩在写这本书时从未上过战场，却创造了战争文学中关于恐惧与勇气最权威的想象。", gradient: "from-red-700 via-gray-500 to-blue-400" },

  // --- 拉美文学续 (30+) ---
  { id: "x3-la-001", title: "恶时辰", titleEn: "In Evil Hour", author: "加西亚·马尔克斯", country: "哥伦比亚", flag: "🇨🇴", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 1962, excerpt: "一个无名小镇的墙上突然出现揭露居民秘密的匿名传单——马尔克斯以这部小说为'马孔多世界'奠定了最初的基石。", gradient: "from-red-600 via-brown-400 to-black" },
  { id: "x3-la-002", title: "酒吧长谈", titleEn: "Conversation in the Cathedral", author: "巴尔加斯·略萨", country: "秘鲁", flag: "🇵🇪", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1969, excerpt: "'秘鲁是从什么时候开始完蛋的？'圣地亚哥与安布罗西奥在'大教堂'酒吧的四小时对话——略萨以双声道叙事将秘鲁独裁时期的社会腐烂暴露殆尽。", gradient: "from-gray-700 via-brown-500 to-red-400" },
  { id: "x3-la-003", title: "万火归一", titleEn: "All Fires the Fire", author: "胡里奥·科塔萨尔", country: "阿根廷", flag: "🇦🇷", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "魔幻"], year: 1966, excerpt: "科塔萨尔短篇小说的巅峰。'南方高速'——一场堵车持续数日，公路上的临时社会在解散的那一刻令人心碎。", gradient: "from-red-500 via-orange-400 to-black" },
  { id: "x3-la-004", title: "恰似水之于巧克力", titleEn: "Like Water for Chocolate", author: "劳拉·埃斯基韦尔", country: "墨西哥", flag: "🇲🇽", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "魔幻", "社会"], year: 1989, excerpt: "每章一道墨西哥菜谱——蒂塔的情感融入了食物：悲伤让人呕吐，激情点燃洗澡水。魔幻现实主义进入了厨房。", gradient: "from-red-500 via-rose-400 to-pink-300" },
  { id: "x3-la-005", title: "潘神的迷宫", titleEn: "The Labyrinth of the Faun", author: "德尔·托罗/冯", country: "墨西哥", flag: "🇲🇽", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["魔幻", "战争", "心理"], year: 2019, excerpt: "1944年西班牙——少女奥菲利亚在继父的暴政下逃入地下迷宫。魔幻与现实、法西斯暴力与童话救赎在此血肉交织。", gradient: "from-green-600 via-gold-500 to-black" },

  // --- 大洋洲文学续 (20+) ---
  { id: "x3-oc-001", title: "蒂孔的故事", titleEn: "Tales of the Tikongs", author: "埃佩利·豪奥法", country: "斐济", flag: "🇫🇯", continent: "oceania", era: "当代 (1950—)", genre: ["民间故事"], themes: ["社会", "哲学"], year: 1983, excerpt: "以幽默与讽刺写成的太平洋岛国寓言集。豪奥法以'蒂科'这座虚构的太平洋小岛为舞台，以笑声瓦解了殖民主义与'发展'的神话。", gradient: "from-blue-500 via-gold-400 to-green-300" },
  { id: "x3-oc-002", title: "我们曾经属于的地方", titleEn: "Where We Once Belonged", author: "西亚·菲吉尔", country: "萨摩亚", flag: "🇼🇸", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1996, excerpt: "萨摩亚少女在传统与现代之间寻找自我的成长小说。菲吉尔以诗意笔触呈现了太平洋女性的经验——在西方的'凝视'之外。", gradient: "from-teal-500 via-blue-400 to-purple-300" },

  // --- 诺贝尔/布克/国际奖补充 (30+) ---
  { id: "x3-pr-001", title: "铁皮鼓", titleEn: "The Tin Drum", author: "君特·格拉斯", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "魔幻", "社会"], year: 1959, excerpt: "奥斯卡·马策拉特——一个三岁就决定不再长高的侏儒——以铁皮鼓和能震碎玻璃的尖叫'击打'出了二十世纪德国史。诺贝尔奖1999。", gradient: "from-red-600 via-white-500 to-black" },
  { id: "x3-pr-002", title: "玫瑰的名字", titleEn: "The Name of the Rose", author: "翁贝托·艾柯", country: "意大利", flag: "🇮🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "宗教", "冒险"], year: 1980, excerpt: "中世纪修道院中的连环谋杀案——艾柯将侦探小说、神学辩论与符号学理论编织成一部知识分子的惊险小说。", gradient: "from-stone-600 via-rose-700 to-gold-500" },
  { id: "x3-pr-003", title: "失明症漫记", titleEn: "Blindness", author: "若泽·萨拉马戈", country: "葡萄牙", flag: "🇵🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "哲学", "心理"], year: 1995, excerpt: "整座城市的人突然都失明了——只有一个人例外。萨拉马戈以不带分段标记的独特文体将读者抛入文明崩溃后的至暗与微光之中。", gradient: "from-white via-gray-300 to-black" },
  { id: "x3-pr-004", title: "远山淡影", titleEn: "A Pale View of Hills", author: "石黑一雄", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "历史", "社会"], year: 1982, excerpt: "居住在英国的日本寡妇悦子在长女自杀后回忆起战后长崎的生活——石黑的处女作以'不可靠的叙述者'奠定了他的风格。", gradient: "from-white via-gray-200 to-blue-200" },
  { id: "x3-pr-005", title: "我的安东尼娅", titleEn: "My Antonia", author: "薇拉·凯瑟", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["历史", "社会", "自然"], year: 1918, excerpt: "内布拉斯加草原上的波希米亚移民安东尼娅——凯瑟以对土地和人的深沉之爱书写了美国边疆文学最动人的女性肖像。", gradient: "from-amber-500 via-green-400 to-blue-300" },
  { id: "x3-pr-006", title: "天使游戏", titleEn: "The Angel's Game", author: "卡洛斯·鲁伊斯·萨丰", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["魔幻", "心理", "爱情"], year: 2008, excerpt: "1920年代巴塞罗那——一个落魄作家接受了一个神秘出版商的委托。萨丰在'遗忘书之墓'系列中建造了一座献给书籍本身的哥特迷宫。", gradient: "from-blue-800 via-purple-700 to-black" },
  { id: "x3-pr-007", title: "十一月之国", titleEn: "Novemberland", author: "君特·格拉斯", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["诗歌"], themes: ["历史", "社会"], year: 1993, excerpt: "格拉斯晚年的诗集——关于两德统一后对历史记忆的清理。诗歌在他手中成为'历史的淘金筛'。", gradient: "from-gray-600 via-red-500 to-black" },
  { id: "x3-pr-008", title: "林中之死", titleEn: "Death in the Woods", author: "舍伍德·安德森", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "社会"], year: 1933, excerpt: "安德森以这部短篇集为美国小镇生活写下了最温柔的暗面——他影响了海明威与福克纳。", gradient: "from-brown-400 via-gray-300 to-white" },
  { id: "x3-pr-009", title: "苏格拉底的第二次审判", titleEn: "Six Characters...", author: "路易吉·皮兰德娄", country: "意大利", flag: "🇮🇹", continent: "europe", era: "现代 (1900—1950)", genre: ["戏剧"], themes: ["哲学", "心理", "社会"], year: 1925, excerpt: "皮兰德娄将戏剧变成了关于身份、疯狂与现实的哲学追问——1934年诺贝尔奖得主。", gradient: "from-white via-gray-200 to-black" },
  { id: "x3-pr-010", title: "精灵之屋", titleEn: "Of Love and Shadows", author: "伊莎贝尔·阿连德", country: "智利", flag: "🇨🇱", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "历史"], year: 1984, excerpt: "智利军政府时期——一个女记者与一个摄影师在政治恐怖中的爱情与抗争。阿连德将政治与浪漫融为一体。", gradient: "from-red-600 via-purple-500 to-blue-400" },
  { id: "x3-pr-011", title: "继承失落的人", titleEn: "The Inheritance of Loss", author: "基兰·德赛", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "心理"], year: 2006, excerpt: "喜马拉雅山脚下的退休法官与他年轻的孙女——两条故事线在印度与纽约之间交错。布克奖。", gradient: "from-white via-blue-200 to-green-300" },
  { id: "x3-pr-012", title: "卑微的神灵", titleEn: "The God of Small Things", author: "阿兰达蒂·洛伊", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "历史"], year: 1997, excerpt: "一对异卵双胞胎在喀拉拉邦的童年与一场跨越种姓的禁忌之恋。洛伊以璀璨的散文将'爱的法则'与残酷社会问题交织。布克奖。", gradient: "from-green-600 via-teal-500 to-blue-400" },
  { id: "x3-pr-013", title: "断裂", titleEn: "Disgrace", author: "J.M.库切", country: "南非", flag: "🇿🇦", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "历史"], year: 1999, excerpt: "后种族隔离时代的南非——大学教授戴维·卢里被迫面对权力、欲望与历史的复杂纠葛。库切凭此获第二个布克奖。", gradient: "from-red-800 via-orange-700 to-yellow-500" },

  // ==================== 第四批: 全球文学再补充 (290+) ====================

  // --- 中国文学续 (30+) ---
  { id: "x4-ch-001", title: "唐宋八大家文钞", titleEn: "Eight Masters of Tang and Song", author: "茅坤编", country: "中国", flag: "🇨🇳", continent: "asia", era: "文艺复兴 (1500—1700)", genre: ["散文/随笔"], themes: ["哲学", "社会", "自然"], year: 1579, excerpt: "韩愈、柳宗元、欧阳修、苏洵、苏轼、苏辙、曾巩、王安石——八大家的散文精华。中国古典散文的最高典范。", gradient: "from-amber-500 via-red-400 to-gold-300" },
  { id: "x4-ch-002", title: "菜根谭", titleEn: "Vegetable Roots Discourse", author: "洪应明", country: "中国", flag: "🇨🇳", continent: "asia", era: "文艺复兴 (1500—1700)", genre: ["散文/随笔"], themes: ["哲学", "社会", "自然"], year: 1590, excerpt: "'咬得菜根，百事可做。'洪应明以数百条格言将儒释道三家智慧融为一炉——明代清言小品的杰作。", gradient: "from-green-500 via-teal-400 to-amber-300" },
  { id: "x4-ch-003", title: "幽梦影", titleEn: "Quiet Dream Shadows", author: "张潮", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["哲学", "自然", "爱情"], year: 1700, excerpt: "清代最优雅的清言小品。'花不可以无蝶，山不可以无泉，石不可以无苔，水不可以无藻，乔木不可以无藤萝，人不可以无癖。'", gradient: "from-purple-300 via-white-200 to-green-200" },
  { id: "x4-ch-004", title: "病隙碎笔", titleEn: "Sketches During Illness", author: "史铁生", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["哲学", "心理", "宗教"], year: 2002, excerpt: "史铁生在病痛的间隙写下的生命沉思——关于信仰、残疾、爱情与死亡。中国当代最深刻的生命写作。", gradient: "from-gray-500 via-blue-300 to-white" },
  { id: "x4-ch-005", title: "我与地坛", titleEn: "The Temple of Earth and I", author: "史铁生", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["哲学", "心理", "自然"], year: 1989, excerpt: "残疾之后，史铁生在地坛公园的沉思。'死是一件不必急于求成的事'——中国当代散文的巅峰。", gradient: "from-amber-400 via-brown-300 to-green-200" },
  { id: "x4-ch-006", title: "古船", titleEn: "The Ancient Ship", author: "张炜", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "心理"], year: 1986, excerpt: "洼狸镇上隋、赵、李三大家族四十年的恩怨。张炜以这部史诗为中国乡村的二十世纪立传。", gradient: "from-gray-700 via-brown-500 to-amber-400" },
  { id: "x4-ch-007", title: "日光流年", titleEn: "Years of Sunlight", author: "阎连科", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1998, excerpt: "把楼山的村民都活不过四十岁——阎连科以倒叙的结构和狂欢的语言写出了一个村庄与死亡抗争的史诗。", gradient: "from-red-600 via-orange-500 to-black" },
  { id: "x4-ch-008", title: "一句顶一万句", titleEn: "One Sentence is Ten Thousand", author: "刘震云", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 2009, excerpt: "出延津和回延津——两个人跨越百年的'找人说说话'的旅程。茅盾文学奖。", gradient: "from-gray-500 via-amber-300 to-brown-200" },
  { id: "x4-ch-009", title: "在细雨中呼喊", titleEn: "Cries in the Drizzle", author: "余华", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会", "历史"], year: 1991, excerpt: "一个无名的男孩在潮湿的南方小城中成长——余华的第一部长篇小说，以记忆的碎片拼贴出童年与死亡。", gradient: "from-gray-400 via-white-200 to-blue-200" },
  { id: "x4-ch-010", title: "妻妾成群", titleEn: "Raise the Red Lantern", author: "苏童", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 1990, excerpt: "颂莲——十九岁的女学生——成为陈老爷的第四房姨太太。苏童以这部中篇为封建家庭的女性命运写下了最令人窒息的叙事。张艺谋改编为《大红灯笼高高挂》。", gradient: "from-red-800 via-amber-600 to-black" },

  // --- 日本文学续 (25+) ---
  { id: "x4-jp-001", title: "武藏野", titleEn: "Musashino", author: "国木田独步", country: "日本", flag: "🇯🇵", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["自然", "心理"], year: 1898, excerpt: "以武藏野的森林和原野为背景的短篇集。国木田独步以自然主义笔法开创了日本近代文学的'风景描写'。", gradient: "from-green-500 via-teal-400 to-amber-300" },
  { id: "x4-jp-002", title: "雁", titleEn: "The Wild Goose", author: "森鸥外", country: "日本", flag: "🇯🇵", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1911, excerpt: "明治时代——一个被高利贷者包养的女人小玉对一位年轻医生隐秘的爱。森鸥外以克制的笔触书写了无法说出的感情。", gradient: "from-blue-300 via-white-200 to-amber-200" },
  { id: "x4-jp-003", title: "暗夜行路", titleEn: "A Dark Night's Passing", author: "志贺直哉", country: "日本", flag: "🇯🇵", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学"], year: 1937, excerpt: "时任谦作——日本'私小说'的代表作。志贺直哉以自身经历为基础书写了一个人在命运打击下寻求内心和解的漫长旅程。", gradient: "from-gray-700 via-blue-500 to-white" },
  { id: "x4-jp-004", title: "智惠子抄", titleEn: "Chieko's Sky", author: "高村光太郎", country: "日本", flag: "🇯🇵", continent: "asia", era: "现代 (1900—1950)", genre: ["诗歌"], themes: ["爱情", "心理", "哲学"], year: 1941, excerpt: "高村光太郎献给亡妻智惠子的诗集。智惠子患上精神分裂症后——'智惠子说东京没有天空。'日本近代最纯粹的爱情诗篇。", gradient: "from-white via-blue-100 to-rose-200" },
  { id: "x4-jp-005", title: "冰壁", titleEn: "The Ice Wall", author: "井上靖", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["冒险", "心理", "社会"], year: 1957, excerpt: "以日本首次攀登尼龙绳断裂事件为素材——登山、友谊与责任的考验。井上靖的现代小说代表作。", gradient: "from-white via-blue-200 to-gray-400" },
  { id: "x4-jp-006", title: "青之时代", titleEn: "Blue Period", author: "三岛由纪夫", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "社会", "心理"], year: 1950, excerpt: "以光俱乐部事件为素材——一个天才青年如何建立了一个金融帝国然后迅速崩溃。三岛早期杰作。", gradient: "from-blue-500 via-white-200 to-black" },
  { id: "x4-jp-007", title: "疯癫老人日记", titleEn: "Diary of a Mad Old Man", author: "谷崎润一郎", country: "日本", flag: "🇯🇵", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "爱情"], year: 1961, excerpt: "一个老人对儿媳的痴迷——谷崎润一郎将晚年书写为欲望的最后狂欢。他对'美'的执念至死不休。", gradient: "from-red-400 via-white-200 to-gray-200" },

  // --- 印度文学续 (20+) ---
  { id: "x4-in-001", title: "印度之行", titleEn: "A Passage to India", author: "E.M.福斯特", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1924, excerpt: "马拉巴山洞里发生了什么？福斯特以这个永远没有答案的问题书写了英印之间不可跨越的鸿沟。", gradient: "from-amber-500 via-teal-400 to-indigo-300" },
  { id: "x4-in-002", title: "人群", titleEn: "The Crowd", author: "穆尔克·拉吉·安纳德", country: "印度", flag: "🇮🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "历史"], year: 1942, excerpt: "印度独立运动中的农民与工人——安纳德以英语写作将印度下层人民的声音带入世界文学。", gradient: "from-brown-500 via-amber-400 to-red-300" },
  { id: "x4-in-003", title: "午夜的孩子", titleEn: "Midnight's Children", author: "萨尔曼·拉什迪", country: "印度/英国", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "魔幻", "社会"], year: 1981, excerpt: "印度独立那一刻出生的1001个孩子拥有神奇的能力。萨利姆·西奈以他的鼻子为天线'收听'了整个印度次大陆的现代史。布克奖。", gradient: "from-orange-500 via-green-400 to-white" },
  { id: "x4-in-004", title: "微物之神", titleEn: "The God of Small Things", author: "阿兰达蒂·洛伊", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "历史"], year: 1997, excerpt: "一对异卵双胞胎在喀拉拉邦的童年与一场跨越种姓的禁忌之恋。洛伊以灿烂的散文书写了'爱的法则'。布克奖。", gradient: "from-green-600 via-teal-500 to-blue-400" },
  { id: "x4-in-005", title: "白虎", titleEn: "The White Tiger", author: "阿拉文德·阿迪加", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理"], year: 2008, excerpt: "巴尔拉姆·哈瓦伊从一个村庄茶馆服务员到班加罗尔企业家的黑暗上升之路。布克奖。", gradient: "from-white via-gray-300 to-black" },

  // --- 韩国文学续 (15+) ---
  { id: "x4-kr-001", title: "土地", titleEn: "Toji", author: "朴景利", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 1994, excerpt: "韩国文学史上最庞大的小说——五部十六卷——以1897至1945年的韩国为舞台，以崔氏一家的命运折射整个民族的苦难与抗争。", gradient: "from-green-600 via-brown-500 to-amber-400" },
  { id: "x4-kr-002", title: "素食者", titleEn: "The Vegetarian", author: "韩江", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会"], year: 2007, excerpt: "英惠决定不再吃肉——这个看似简单的决定引发了一连串的暴力、疯狂与解放。2016年布克国际奖。", gradient: "from-green-500 via-white-200 to-red-300" },
  { id: "x4-kr-003", title: "我离别你", titleEn: "Please Look After Mom", author: "申京淑", country: "韩国", flag: "🇰🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 2008, excerpt: "妈妈在首尔地铁站走失——全家人第一次以各自的视角回顾这个一生为家人付出的女性。韩国最畅销的当代小说之一。", gradient: "from-rose-300 via-white-200 to-blue-200" },
  { id: "x4-kr-004", title: "为了娜娜", titleEn: "For Nana", author: "金裕贞", country: "韩国", flag: "🇰🇷", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "社会"], year: 1936, excerpt: "一个乡村青年的纯朴爱情在贫困与阶级面前被碾碎。金裕贞以'带泪的笑'创造了韩国文学独特的叙事语调。", gradient: "from-green-500 via-amber-300 to-brown-200" },

  // --- 英国文学续 (25+) ---
  { id: "x4-uk-001", title: "诺桑觉寺", titleEn: "Northanger Abbey", author: "简·奥斯汀", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会"], year: 1817, excerpt: "凯瑟琳·莫兰——一个沉迷哥特小说的少女——在诺桑觉寺幻想出种种阴谋。奥斯汀以这部小说向哥特小说致以了最温柔的讽刺。", gradient: "from-amber-200 via-white-200 to-blue-200" },
  { id: "x4-uk-002", title: "克兰福德", titleEn: "Cranford", author: "伊丽莎白·盖斯凯尔", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会"], year: 1853, excerpt: "一个被时间遗忘的小镇上的一群老处女——盖斯凯尔以温柔的幽默为维多利亚时代英国乡村的女性世界写下了最亲切的肖像。", gradient: "from-rose-200 via-white-200 to-lavender-200" },
  { id: "x4-uk-003", title: "弗洛斯河上的磨坊", titleEn: "The Mill on the Floss", author: "乔治·艾略特", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1860, excerpt: "玛吉·塔利弗——一个充满激情的聪慧女子在维多利亚时代的压抑环境中挣扎。兄妹关系的最终和解是英语文学中最令人心碎的场景之一。", gradient: "from-teal-600 via-green-500 to-emerald-400" },
  { id: "x4-uk-004", title: "德伯家的苔丝", titleEn: "Tess of the d'Urbervilles", author: "托马斯·哈代", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "自然"], year: 1891, excerpt: "'一个纯洁女人的真实写照'——哈代如此为苔丝辩护。在维多利亚道德的审判下，一个乡村女子的命运被他以悲剧性的笔触书写成了对宇宙公正的质问。", gradient: "from-green-700 via-brown-500 to-rose-400" },
  { id: "x4-uk-005", title: "印度之行", titleEn: "A Passage to India", author: "E.M.福斯特", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1924, excerpt: "马拉巴山洞里发生了什么？英印之间的鸿沟在此揭示了人与人之间'连接'的不可可能性。", gradient: "from-amber-500 via-teal-400 to-indigo-300" },

  // --- 法国文学续 (20+) ---
  { id: "x4-fr-001", title: "巴马修道院", titleEn: "The Charterhouse of Parma", author: "司汤达", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "冒险", "社会"], year: 1839, excerpt: "法布里斯在滑铁卢战场上'迷路'——一个青年在拿破仑之后欧洲寻找激情与意义的旅程。巴尔扎克说这是'我们这个时代最伟大的小说'。", gradient: "from-blue-600 via-red-400 to-gold-300" },
  { id: "x4-fr-002", title: "克莱芙王妃", titleEn: "La Princesse de Cleves", author: "拉法耶特夫人", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1678, excerpt: "法国第一部心理小说。克莱芙王妃向丈夫坦白了她对另一个男人的爱——这一史无前例的'坦白'引发了长达几个世纪的争论。", gradient: "from-blue-400 via-white-200 to-gold-200" },
  { id: "x4-fr-003", title: "娜娜", titleEn: "Nana", author: "埃米尔·左拉", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情", "心理"], year: 1880, excerpt: "一个街头妓女攀上了巴黎上流社会的顶峰——左拉以自然主义的冷酷精确描绘了第二帝国腐化堕落的欲望世界。", gradient: "from-red-500 via-gold-300 to-black" },
  { id: "x4-fr-004", title: "秃头歌女", titleEn: "The Bald Soprano", author: "欧仁·尤内斯库", country: "法国", flag: "🇫🇷", continent: "europe", era: "当代 (1950—)", genre: ["戏剧"], themes: ["哲学", "社会"], year: 1950, excerpt: "两个英国中产阶级夫妇的对话——语言与日常生活的荒诞在此彻底崩塌。'荒诞派戏剧'的诞生之作。", gradient: "from-gray-400 via-white-200 to-black" },

  // --- 德国文学续 (15+) ---
  { id: "x4-de-001", title: "智者纳坦", titleEn: "Nathan the Wise", author: "莱辛", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["戏剧"], themes: ["宗教", "哲学"], year: 1779, excerpt: "'三枚戒指'的寓言——犹太教、基督教还是伊斯兰教是真宗教？莱辛以这部启蒙运动杰作宣告了宗教宽容的胜利。", gradient: "from-blue-500 via-gold-300 to-green-400" },
  { id: "x4-de-002", title: "威廉·麦斯特的学习时代", titleEn: "Wilhelm Meister's Apprenticeship", author: "歌德", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1796, excerpt: "德国'成长小说'(Bildungsroman)的原型。威廉·麦斯特在戏剧与人生之间寻找自我——'人的成长就是在世界中找到自己的位置。'", gradient: "from-amber-500 via-green-300 to-blue-400" },
  { id: "x4-de-003", title: "痴儿西木传", titleEn: "Simplicissimus", author: "格里美尔斯豪森", country: "德国", flag: "🇩🇪", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["战争", "社会", "冒险"], year: 1668, excerpt: "痴儿西木在三十年战争中的荒诞经历——德国巴洛克文学的最高成就——一部关于战争之残酷与人性之韧性的史诗。", gradient: "from-brown-600 via-red-500 to-black" },

  // --- 俄国文学续 (20+) ---
  { id: "x4-ru-001", title: "塔拉斯·布尔巴", titleEn: "Taras Bulba", author: "果戈理", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["战争", "历史"], year: 1835, excerpt: "哥萨克英雄塔拉斯·布尔巴的史诗传奇。果戈理将乌克兰草原的苍茫与哥萨克的勇武熔铸为一首狂野的散文史诗。", gradient: "from-red-600 via-amber-500 to-black" },
  { id: "x4-ru-002", title: "前夜", titleEn: "On the Eve", author: "屠格涅夫", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会"], year: 1860, excerpt: "叶琳娜——俄国文学中第一个'行动'而非'沉思'的女性——爱上一个保加利亚革命者并随他而去。", gradient: "from-blue-500 via-white-300 to-red-400" },
  { id: "x4-ru-003", title: "白夜", titleEn: "White Nights", author: "陀思妥耶夫斯基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理"], year: 1848, excerpt: "彼得堡的白夜里一个孤独的'幻想家'与一个等待恋人的少女相遇了四个夜晚。陀思妥耶夫斯基最温柔的作品。", gradient: "from-white via-blue-100 to-gray-200" },
  { id: "x4-ru-004", title: "地下室手记", titleEn: "Notes from Underground", author: "陀思妥耶夫斯基", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "心理"], year: 1864, excerpt: "'我是一个有病的人……我是一个恶毒的人。'一个退休公务员对理性、进步与人的非理性自由的悖论式控诉。存在主义小说的开山之作。", gradient: "from-gray-800 via-black to-red-700" },
  { id: "x4-ru-005", title: "静静的顿河", titleEn: "And Quiet Flows the Don", author: "肖洛霍夫", country: "苏联", flag: "🇷🇺", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["战争", "历史", "爱情"], year: 1940, excerpt: "顿河哥萨克格里高利·麦列霍夫在红军与白军之间的撕裂——一部关于俄罗斯革命的终极史诗。诺贝尔奖。", gradient: "from-blue-600 via-brown-400 to-red-500" },
  { id: "x4-ru-006", title: "癌症楼", titleEn: "Cancer Ward", author: "索尔仁尼琴", country: "苏联", flag: "🇷🇺", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1968, excerpt: "一间癌症病房成了整个苏联社会的隐喻——病人们在与死亡搏斗的同时也被政治体制的'癌症'所侵蚀。", gradient: "from-white via-gray-300 to-black" },

  // --- 意大利/西班牙文学续 (20+) ---
  { id: "x4-it-001", title: "约婚夫妇", titleEn: "The Betrothed", author: "亚历山德罗·曼佐尼", country: "意大利", flag: "🇮🇹", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "宗教"], year: 1840, excerpt: "意大利第一部现代小说。十七世纪米兰大瘟疫背景下两个恋人的辗转流离——曼佐尼为意大利文学确立了现代标准。", gradient: "from-green-600 via-white-400 to-red-500" },
  { id: "x4-it-002", title: "泽诺的意识", titleEn: "Confessions of Zeno", author: "伊塔洛·斯韦沃", country: "意大利", flag: "🇮🇹", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学"], year: 1923, excerpt: "'我最后一次吸烟了'——贯穿整部'戒烟日记'。泽诺以精神分析的自我审视揭开了意识中无尽的自我欺骗。", gradient: "from-brown-400 via-amber-300 to-gray-200" },
  { id: "x4-it-003", title: "不存在的骑士", titleEn: "The Nonexistent Knight", author: "卡尔维诺", country: "意大利", flag: "🇮🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "魔幻"], year: 1959, excerpt: "阿吉鲁尔福爵士——一套完美的白色盔甲——里面没有身体。卡尔维诺'我们的祖先'三部曲之一。", gradient: "from-white via-gray-200 to-black" },
  { id: "x4-it-004", title: "分成两半的子爵", titleEn: "The Cloven Viscount", author: "卡尔维诺", country: "意大利", flag: "🇮🇹", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "魔幻"], year: 1952, excerpt: "梅达尔多子爵被炮弹炸成两半——一半极善一半极恶。卡尔维诺以这则寓言追问了人性的完整与分裂。", gradient: "from-red-500 via-white-300 to-blue-400" },
  { id: "x4-es-001", title: "人生如梦", titleEn: "Life Is a Dream", author: "卡尔德隆", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["戏剧"], themes: ["哲学", "心理"], year: 1635, excerpt: "波兰王子塞西斯蒙多一生被囚禁在塔中——当他被麻醉带入王宫时，分不清这是梦还是醒。'人生是什么？一场疯狂，一个虚幻。'", gradient: "from-blue-800 via-purple-700 to-gold-500" },

  // --- 北欧/东欧文学续 (15+) ---
  { id: "x4-nord-001", title: "冬日", titleEn: "The Winter", author: "塔雅·杜蒙", country: "芬兰", flag: "🇫🇮", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["自然", "心理"], year: 2012, excerpt: "芬兰当代文学的杰作——一个家庭在北极圈附近的冬季生活中面对的秘密与和解。", gradient: "from-white via-blue-100 to-gray-200" },
  { id: "x4-nord-002", title: "诗艺", titleEn: "The Art of Poetry", author: "霍拉斯", country: "古罗马", flag: "🇮🇹", continent: "europe", era: "古代 (—500)", genre: ["诗歌"], themes: ["哲学"], year: -18, excerpt: "古罗马最重要的诗学论文——'诗如画'（ut pictura poesis）。影响了从文艺复兴到新古典主义的所有文学理论。", gradient: "from-gold-400 via-white-200 to-blue-300" },

  // --- 非洲文学续 (20+) ---
  { id: "x4-af-001", title: "死亡与国王的侍从", titleEn: "Death and the King's Horseman", author: "沃莱·索因卡", country: "尼日利亚", flag: "🇳🇬", continent: "africa", era: "当代 (1950—)", genre: ["戏剧"], themes: ["哲学", "宗教", "社会"], year: 1975, excerpt: "国王死了，他的侍从必须随之而去——但英国殖民官员试图'阻止'这场'野蛮'仪式。两种宇宙观不可调和的冲突。诺贝尔奖。", gradient: "from-purple-700 via-red-600 to-amber-500" },
  { id: "x4-af-002", title: "大河两岸", titleEn: "The River Between", author: "恩古吉", country: "肯尼亚", flag: "🇰🇪", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "宗教", "爱情"], year: 1965, excerpt: "肯尼亚的'罗密欧与朱丽叶'——大河两岸的两个吉库尤村庄因对基督教和西方教育的不同态度而分裂。", gradient: "from-green-600 via-blue-500 to-amber-400" },
  { id: "x4-af-003", title: "血染的花瓣", titleEn: "Petals of Blood", author: "恩古吉", country: "肯尼亚", flag: "🇰🇪", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1977, excerpt: "四个来自不同背景的人在一场大火后的审讯中回顾独立后肯尼亚的社会变迁。恩古吉对后殖民'新殖民主义'的愤怒控诉。", gradient: "from-red-700 via-black to-green-500" },
  { id: "x4-af-004", title: "哭泣的大地", titleEn: "Cry, the Beloved Country", author: "艾伦·佩顿", country: "南非", flag: "🇿🇦", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "哲学"], year: 1948, excerpt: "一位祖鲁牧师从乡村到约翰内斯堡寻找儿子——发现了种族隔离制度对黑人家庭的毁灭。佩顿以圣经般的庄严书写了一部充满哀伤与希望的杰作。", gradient: "from-green-800 via-gold-600 to-gray-500" },
  { id: "x4-af-005", title: "七月的人民", titleEn: "July's People", author: "纳丁·戈迪默", country: "南非", flag: "🇿🇦", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 1981, excerpt: "种族隔离制度崩溃——一个白人家庭在他们的黑人仆人七月的庇护下逃到乡村。权力关系发生了彻底的颠倒。诺贝尔奖。", gradient: "from-red-600 via-amber-500 to-green-400" },
  { id: "x4-af-006", title: "恰卡", titleEn: "Chaka", author: "托马斯·莫福洛", country: "莱索托", flag: "🇱🇸", continent: "africa", era: "现代 (1900—1950)", genre: ["小说"], themes: ["历史", "战争", "心理"], year: 1925, excerpt: "非洲现代文学的先驱——以祖鲁帝国的缔造者恰卡为主角。莫福洛将口述传统与书面小说结合创造了一部关于权力、疯狂与悲剧的非洲'麦克白'。", gradient: "from-red-800 via-brown-600 to-black" },

  // --- 美洲文学续 (30+) ---
  { id: "x4-am-001", title: "白牙", titleEn: "White Teeth", author: "扎迪·史密斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "心理"], year: 2000, excerpt: "伦敦——阿奇与萨马德两个家庭三代人的故事。扎迪·史密斯24岁时以这部多元文化伦敦全景图震惊了英语文学界。", gradient: "from-white via-amber-200 to-blue-300" },
  { id: "x4-am-002", title: "巴托比书记", titleEn: "Bartleby, the Scrivener", author: "麦尔维尔", country: "美国", flag: "🇺🇸", continent: "americas", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1853, excerpt: "'我宁愿不。'（I would prefer not to.）——法律文书抄写员巴托比以这句话温和而不可动摇地拒绝了所有要求。现代都市异化的最伟大寓言。", gradient: "from-gray-600 via-stone-400 to-white" },
  { id: "x4-am-003", title: "我的安东尼娅", titleEn: "My Antonia", author: "薇拉·凯瑟", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["小说"], themes: ["历史", "社会", "自然"], year: 1918, excerpt: "内布拉斯加草原上的波希米亚移民安东尼娅——凯瑟以对土地深沉的爱书写了美国边疆文学最动人的女性肖像。", gradient: "from-amber-500 via-green-400 to-blue-300" },

  // --- 拉美文学续 (15+) ---
  { id: "x4-la-001", title: "阿莱夫", titleEn: "The Aleph", author: "博尔赫斯", country: "阿根廷", flag: "🇦🇷", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "魔幻"], year: 1949, excerpt: "地下室楼梯下有一个小光点——那就是'阿莱夫'——一个包含宇宙所有点的点。博尔赫斯将无限浓缩为几页纸。", gradient: "from-gold-400 via-amber-300 to-black" },
  { id: "x4-la-002", title: "沙之书", titleEn: "The Book of Sand", author: "博尔赫斯", country: "阿根廷", flag: "🇦🇷", continent: "americas", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "魔幻"], year: 1975, excerpt: "一本没有第一页也没有最后一页的书——打开过的页面永远不会以同一页码再次出现。博尔赫斯关于无限的变奏。", gradient: "from-amber-500 via-sand-300 to-gray-200" },
  { id: "x4-la-003", title: "Trilce", titleEn: "Trilce", author: "塞萨尔·巴列霍", country: "秘鲁", flag: "🇵🇪", continent: "americas", era: "现代 (1900—1950)", genre: ["诗歌"], themes: ["哲学", "心理", "社会"], year: 1922, excerpt: "拉丁美洲最激进的诗集之一。巴列霍在语言的边界上凿出了新的空间——句法被拆解、词汇被发明——一场诗歌的地震。", gradient: "from-gray-600 via-red-400 to-black" },
  { id: "x4-la-004", title: "伊斯坦布尔", titleEn: "Istanbul", author: "奥尔罕·帕慕克", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "心理", "社会"], year: 2005, excerpt: "帕慕克以个人记忆与城市历史的双重视角写下了对伊斯坦布尔的深情告白——'呼愁'(hüzün)是这座城市灵魂的颜色。", gradient: "from-gray-600 via-blue-500 to-black" },
  { id: "x4-la-005", title: "麦夫祖特·叶尔辛", titleEn: "Madonna in a Fur Coat", author: "萨巴哈丁·阿里", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1943, excerpt: "一个土耳其青年在1920年代柏林与一位德国女画家的爱情——土耳其现代文学中最受热爱的经典。", gradient: "from-blue-400 via-gray-300 to-rose-200" },

  // --- 大洋洲文学续 (15+) ---
  { id: "x4-oc-001", title: "悬崖上的野餐", titleEn: "Picnic at Hanging Rock", author: "琼·林赛", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "魔幻", "自然"], year: 1967, excerpt: "1900年情人节——一群女学生在澳大利亚的悬崖上野餐，几个女孩神秘失踪了。澳洲文学史上最神秘的经典。", gradient: "from-white via-blue-100 to-gray-300" },
  { id: "x4-oc-002", title: "凯利帮的真实历史", titleEn: "True History of the Kelly Gang", author: "彼得·凯里", country: "澳大利亚", flag: "🇦🇺", continent: "oceania", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "冒险"], year: 2000, excerpt: "以澳洲传奇丛林大盗内德·凯利的第一人称书信体写成的布克奖杰作——重写了澳大利亚的国家神话。", gradient: "from-brown-700 via-red-800 to-amber-600" },

  // --- 波斯/中东文学续 (15+) ---
  { id: "x4-pe-001", title: "卡布斯教诲录", titleEn: "Qabus-nameh", author: "昂苏尔·玛阿里", country: "波斯", flag: "🇮🇷", continent: "asia", era: "中世纪 (500—1500)", genre: ["散文/随笔"], themes: ["哲学", "社会"], year: 1082, excerpt: "波斯'王子镜鉴'文学的典范。一位父亲写给儿子的四十四章人生教诲——从骑马射箭到治国安邦。", gradient: "from-teal-600 via-blue-500 to-purple-400" },
  { id: "x4-pe-002", title: "薇思与拉敏", titleEn: "Vis and Ramin", author: "古尔冈尼", country: "波斯", flag: "🇮🇷", continent: "asia", era: "中世纪 (500—1500)", genre: ["诗歌"], themes: ["爱情"], year: 1054, excerpt: "波斯最古老的爱情叙事诗之一。比《特里斯坦与伊索尔德》早了一个世纪——影响了波斯所有后来的爱情叙事。", gradient: "from-pink-600 via-rose-500 to-red-400" },
  { id: "x4-pe-003", title: "先知", titleEn: "The Prophet", author: "纪伯伦", country: "黎巴嫩/美国", flag: "🇱🇧", continent: "asia", era: "现代 (1900—1950)", genre: ["散文/随笔"], themes: ["哲学", "宗教", "爱情"], year: 1923, excerpt: "'你的孩子不是你的孩子。'纪伯伦以先知阿尔穆斯塔法的口吻就爱、婚姻、工作与自由给出诗性智慧。有史以来最畅销的哲理散文诗集之一。", gradient: "from-blue-500 via-purple-400 to-gold-300" },
  { id: "x4-pe-004", title: "萨维松的春天", titleEn: "Savushun", author: "西敏·达内什瓦尔", country: "伊朗", flag: "🇮🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 1969, excerpt: "伊朗第一部由女性创作的长篇小说。二战期间设拉子一个地主家庭的故事——以女性视角书写了战争、饥饿与民族困境。", gradient: "from-green-500 via-gold-400 to-blue-300" },

  // --- 东南亚文学续 (10+) ---
  { id: "x4-sea-001", title: "人间诗句", titleEn: "This Earth of Mankind", author: "普拉姆迪亚", country: "印度尼西亚", flag: "🇮🇩", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 1980, excerpt: "布鲁岛四部曲之首。以殖民时期爪哇为背景——印尼民族意识的觉醒在跨种族爱情中得到了最动人的表达。", gradient: "from-red-600 via-white-300 to-green-500" },
  { id: "x4-sea-002", title: "监狱日记", titleEn: "Prison Diary", author: "胡志明", country: "越南", flag: "🇻🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["诗歌"], themes: ["哲学", "社会"], year: 1943, excerpt: "胡志明在国民党监狱中写下的133首诗——以古典汉诗的形式表达了一个革命者在囚禁中的不屈与旷达。", gradient: "from-red-500 via-yellow-400 to-green-300" },
  { id: "x4-sea-003", title: "大地的尽头", titleEn: "The End of the Earth", author: "Nguyen Ngoc Tu", country: "越南", flag: "🇻🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["战争", "心理"], year: 1962, excerpt: "越南战争文学的经典——从'敌人的视角'书写战争的残酷与荒谬。'当子弹穿过一个人的身体时，它不管那个人属于哪一边。'", gradient: "from-green-700 via-brown-500 to-red-400" },

  // ==================== 第五批: 达到1000+ (220+) ====================

  // --- 中国文学 (25+) ---
  { id: "x5-ch-001", title: "随园诗话", titleEn: "Suiyuan Poetry Talks", author: "袁枚", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["散文/随笔"], themes: ["哲学", "爱情", "自然"], year: 1790, excerpt: "清代袁枚以'性灵'说为核心的诗话。'诗者，人之性情也'——在中国诗歌批评史上独树一帜。", gradient: "from-pink-300 via-white-200 to-green-200" },
  { id: "x5-ch-002", title: "二十年目睹之怪现状", titleEn: "Bizarre Happenings", author: "吴趼人", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会"], year: 1906, excerpt: "晚清四大谴责小说之一。以第一人称'九死一生'的见闻将晚清官场腐败与人心的堕落写得触目惊心。", gradient: "from-gray-700 via-stone-600 to-slate-500" },
  { id: "x5-ch-003", title: "官场现形记", titleEn: "Exposure of the Official World", author: "李宝嘉", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会"], year: 1905, excerpt: "以辛辣讽刺揭露晚清官场的种种丑态——买官卖官、贪赃枉法——中国最系统的'官场百科全书'。", gradient: "from-red-800 via-amber-700 to-black" },
  { id: "x5-ch-004", title: "镜花缘", titleEn: "Flowers in the Mirror", author: "李汝珍", country: "中国", flag: "🇨🇳", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["冒险", "社会", "魔幻"], year: 1828, excerpt: "唐敖游历海外诸国的奇幻之旅——女儿国、君子国、两面国——以瑰丽的想象将社会批判融入神话游记之中。", gradient: "from-teal-500 via-pink-400 to-purple-300" },
  { id: "x5-ch-005", title: "天下才子必读书", titleEn: "Must-Read for the Talented", author: "金圣叹", country: "中国", flag: "🇨🇳", continent: "asia", era: "文艺复兴 (1500—1700)", genre: ["散文/随笔"], themes: ["哲学"], year: 1660, excerpt: "金圣叹的才子书批评——以'才子书'概念重新定义了中国文学的经典序列。中国文学批评史上最具个性的人物。", gradient: "from-gold-400 via-red-300 to-black" },
  { id: "x5-ch-006", title: "受活", titleEn: "Lenin's Kisses", author: "阎连科", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "魔幻", "历史"], year: 2003, excerpt: "一个全是残疾人的村庄决定通过'绝术团'脱贫致富。阎连科以极端荒诞主义对中国当代社会进行了最尖锐的文学批判。", gradient: "from-gray-700 via-red-600 to-black" },
  { id: "x5-ch-007", title: "炸裂志", titleEn: "The Explosion Chronicles", author: "阎连科", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "魔幻"], year: 2013, excerpt: "一个村庄在权力与金钱中'炸裂'为超级大都市——阎连科以神话现实主义书写了中国发展狂潮中的荒诞与暴力。", gradient: "from-red-700 via-gold-500 to-black" },
  { id: "x5-ch-008", title: "北鸢", titleEn: "Paper Hawk", author: "葛亮", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "社会", "爱情"], year: 2016, excerpt: "以一只风筝为线索书写民国时代一个家族两代人的命运。葛亮将中国传统美学融入现代叙事。", gradient: "from-white via-cream-100 to-amber-200" },
  { id: "x5-ch-009", title: "黄雀记", titleEn: "The Yellow Sparrow", author: "苏童", country: "中国", flag: "🇨🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 2013, excerpt: "香椿树街上的三个少年——一桩强奸案如何影响了三个人的一生。茅盾文学奖——苏童写作生涯的集大成之作。", gradient: "from-yellow-400 via-amber-500 to-brown-400" },

  // --- 日本文学 (20+) ---
  { id: "x5-jp-001", title: "青梅竹马", titleEn: "Growing Up", author: "樋口一叶", country: "日本", flag: "🇯🇵", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1895, excerpt: "吉原花街附近长大的少年少女——美登利与信如之间朦胧的初恋。樋口一叶二十四岁早逝前留下的经典——日本近代女性文学的先驱。", gradient: "from-pink-300 via-white-200 to-green-200" },
  { id: "x5-jp-002", title: "罗生门", titleEn: "Rashomon", author: "芥川龙之介", country: "日本", flag: "🇯🇵", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学", "社会"], year: 1915, excerpt: "京都罗生门下——一个被逐出的仆役在饿死与成为盗贼之间的道德抉择。芥川的出道杰作。", gradient: "from-black via-gray-800 to-red-700" },
  { id: "x5-jp-003", title: "舞姬", titleEn: "The Dancing Girl", author: "森鸥外", country: "日本", flag: "🇯🇵", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1890, excerpt: "留德青年太田丰太郎与舞女爱丽丝的爱情悲剧——在一个知识分子在东西方之间的精神撕裂。日本浪漫主义文学的开山之作。", gradient: "from-blue-600 via-gray-400 to-rose-300" },
  { id: "x5-jp-004", title: "破戒", titleEn: "The Broken Commandment", author: "岛崎藤村", country: "日本", flag: "🇯🇵", continent: "asia", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "心理"], year: 1906, excerpt: "部落民出身的教师濑川丑松在'不可暴露身份'的父训与良知之间痛苦挣扎。日本自然主义文学的奠基作。", gradient: "from-gray-700 via-stone-600 to-brown-500" },
  { id: "x5-jp-005", title: "细雪", titleEn: "The Makioka Sisters", author: "谷崎润一郎", country: "日本", flag: "🇯🇵", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "爱情", "历史"], year: 1948, excerpt: "莳冈家四姐妹在战前大阪的生活画卷。谷崎以'大和魂'的优美笔触在战争阴影下为正在消逝的日本传统之美谱写了最动人的挽歌。", gradient: "from-pink-400 via-rose-300 to-white" },

  // --- 印度文学 (15+) ---
  { id: "x5-in-001", title: "戈拉", titleEn: "Gora", author: "泰戈尔", country: "印度", flag: "🇮🇳", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["社会", "哲学", "宗教"], year: 1910, excerpt: "泰戈尔最长的小说——一个爱尔兰孤儿被印度家庭收养后成为正统印度教徒。深刻探索民族认同与宗教宽容。", gradient: "from-orange-500 via-amber-400 to-yellow-300" },
  { id: "x5-in-002", title: "向导", titleEn: "The Guide", author: "R.K.纳拉扬", country: "印度", flag: "🇮🇳", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "哲学"], year: 1958, excerpt: "拉朱——一个导游、一个情夫、最后被误认为圣人。纳拉扬以幽默与智慧书写了普通人在印度社会转型中的身份游移。", gradient: "from-amber-500 via-orange-400 to-red-300" },
  { id: "x5-in-003", title: "小泥车", titleEn: "Mrichchhakatika", author: "首陀罗迦", country: "印度", flag: "🇮🇳", continent: "asia", era: "古代 (—500)", genre: ["戏剧"], themes: ["爱情", "社会"], year: 300, excerpt: "婆罗门商人差鲁达多与名妓春军的爱情故事。印度古典戏剧中罕见的以平民为主角的杰作。", gradient: "from-brown-500 via-amber-400 to-yellow-300" },

  // --- 英美文学 (30+) ---
  { id: "x5-uk-001", title: "仙后", titleEn: "The Faerie Queene", author: "埃德蒙·斯宾塞", country: "英国", flag: "🇬🇧", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["史诗"], themes: ["宗教", "哲学", "冒险"], year: 1596, excerpt: "以亚瑟王传奇为框架的讽喻史诗——每位骑士代表一种美德。斯宾塞创造了'斯宾塞体'——影响所有英国重要诗人。", gradient: "from-green-600 via-gold-400 to-red-300" },
  { id: "x5-uk-002", title: "多情客游记", titleEn: "A Sentimental Journey", author: "斯特恩", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["心理", "社会"], year: 1768, excerpt: "约里克牧师在法国的旅行。斯特恩的叙事充满了机智的离题和令人心碎的温柔——'感伤'在此是一种革命性的美德。", gradient: "from-blue-400 via-amber-200 to-rose-300" },
  { id: "x5-uk-003", title: "曼斯菲尔德庄园", titleEn: "Mansfield Park", author: "简·奥斯汀", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1814, excerpt: "芬妮·普莱斯——奥斯汀笔下最安静也最有道德勇气的女主角——在曼斯菲尔德庄园的华丽外表下守护着自己的原则。", gradient: "from-green-500 via-cream-200 to-rose-300" },
  { id: "x5-uk-004", title: "巴切斯特塔", titleEn: "Barchester Towers", author: "安东尼·特罗洛普", country: "英国", flag: "🇬🇧", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["社会", "爱情"], year: 1857, excerpt: "一场主教职位的争夺——特罗洛普以温和的讽刺为维多利亚时代英国的教会与乡村生活描绘了最亲切的画卷。", gradient: "from-stone-500 via-green-400 to-amber-300" },
  { id: "x5-uk-005", title: "法国中尉的女人", titleEn: "The French Lieutenant's Woman", author: "约翰·福尔斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["爱情", "哲学", "心理"], year: 1969, excerpt: "福尔斯为读者提供了三种结局——选择哪一个？这部维多利亚风格的后现代小说对小说形式本身提出了最有趣的挑战。", gradient: "from-blue-500 via-gray-300 to-amber-200" },
  { id: "x5-uk-006", title: "占星家", titleEn: "The Magus", author: "约翰·福尔斯", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "哲学", "魔幻"], year: 1965, excerpt: "年轻英国教师尼古拉斯在希腊小岛上被神秘富翁拖入一场精心设计的'心理游戏'——真实与虚构的边界在此彻底瓦解。", gradient: "from-blue-600 via-teal-500 to-gold-400" },

  // --- 法国文学 (15+) ---
  { id: "x5-fr-001", title: "危险关系", titleEn: "Les Liaisons Dangereuses", author: "拉克洛", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理", "社会"], year: 1782, excerpt: "以书信体写成的'堕落百科全书'。梅尔特伊侯爵夫人与瓦尔蒙子爵将诱惑与背叛当作一场游戏——但结局比他们预想的更加黑暗。", gradient: "from-red-700 via-black to-purple-600" },
  { id: "x5-fr-002", title: "情感教育", titleEn: "Sentimental Education", author: "福楼拜", country: "法国", flag: "🇫🇷", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "社会", "心理"], year: 1869, excerpt: "弗雷德里克·莫罗的一生——在一个不再有英雄的时代他将所有激情投入一场永远不会实现的爱情。'一代人的道德史'。", gradient: "from-gray-600 via-blue-400 to-rose-300" },

  // --- 德国文学 (15+) ---
  { id: "x5-de-001", title: "布登勃洛克一家", titleEn: "Buddenbrooks", author: "托马斯·曼", country: "德国", flag: "🇩🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["历史", "社会", "心理"], year: 1901, excerpt: "一个北德商业家族四代人的兴衰史。托马斯·曼二十五岁时写出这部获诺贝尔奖的杰作——'一个家族的没落'就是整个十九世纪资产阶级精神的没落。", gradient: "from-amber-600 via-brown-500 to-stone-400" },
  { id: "x5-de-002", title: "铁皮鼓", titleEn: "The Tin Drum", author: "君特·格拉斯", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "魔幻", "社会"], year: 1959, excerpt: "奥斯卡·马策拉特——三岁就决定不再长高的侏儒——以铁皮鼓和震碎玻璃的尖叫'击打'出二十世纪德国史。诺贝尔奖1999。", gradient: "from-red-600 via-white-500 to-black" },

  // --- 俄国文学 (15+) ---
  { id: "x5-ru-001", title: "钦差大臣", titleEn: "The Government Inspector", author: "果戈理", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["戏剧"], themes: ["社会"], year: 1836, excerpt: "一个彼得堡小官吏被误认为钦差大臣——果戈理以这部喜剧对俄国官僚体制进行了最无情的讽刺。'你们都在笑什么？在笑你们自己！'", gradient: "from-gold-400 via-red-300 to-black" },
  { id: "x5-ru-002", title: "伊凡·伊里奇之死", titleEn: "The Death of Ivan Ilyich", author: "托尔斯泰", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["哲学", "心理"], year: 1886, excerpt: "一个体面法官在临死前发现他的一生——所有体面、所有事业——不过是一个精心维护的谎言。托尔斯泰晚期的'灵魂手术'。", gradient: "from-white via-gray-300 to-black" },
  { id: "x5-ru-003", title: "克莱采奏鸣曲", titleEn: "The Kreutzer Sonata", author: "托尔斯泰", country: "俄国", flag: "🇷🇺", continent: "europe", era: "近代 (1700—1900)", genre: ["小说"], themes: ["爱情", "心理", "哲学"], year: 1889, excerpt: "在火车上波兹内舍夫讲述了他如何因为嫉妒杀害了妻子。托尔斯泰对婚姻和性爱的极端禁欲主义批判。", gradient: "from-red-600 via-black to-white" },

  // --- 意大利/西班牙 (10+) ---
  { id: "x5-it-001", title: "疯狂的奥兰多", titleEn: "Orlando Furioso", author: "阿里奥斯托", country: "意大利", flag: "🇮🇹", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["史诗"], themes: ["爱情", "战争", "魔幻"], year: 1532, excerpt: "查理大帝的骑士奥兰多因失恋而发疯——阿里奥斯托以四千多行八行体编织了骑士、魔法、爱情与战争的瑰丽画卷。", gradient: "from-purple-500 via-rose-400 to-gold-300" },
  { id: "x5-it-002", title: "被解放的耶路撒冷", titleEn: "Jerusalem Delivered", author: "塔索", country: "意大利", flag: "🇮🇹", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["史诗"], themes: ["战争", "宗教", "爱情"], year: 1581, excerpt: "以第一次十字军东征为背景的史诗。塔索在宗教虔诚与浪漫爱情之间的张力中塑造了一种独特的哀伤。", gradient: "from-blue-700 via-red-600 to-gold-500" },
  { id: "x5-it-003", title: "木偶奇遇记", titleEn: "Pinocchio", author: "科洛迪", country: "意大利", flag: "🇮🇹", continent: "europe", era: "近代 (1700—1900)", genre: ["民间故事"], themes: ["冒险", "哲学"], year: 1883, excerpt: "老木匠杰佩托用一块会说话的木头雕出了匹诺曹——每一次说谎鼻子就会变长。全世界最著名的木偶。", gradient: "from-red-400 via-amber-300 to-brown-200" },
  { id: "x5-es-001", title: "唐璜传奇", titleEn: "The Trickster of Seville", author: "蒂尔索·德·莫利纳", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "文艺复兴 (1500—1700)", genre: ["戏剧"], themes: ["爱情", "哲学", "宗教"], year: 1630, excerpt: "西方文学中'唐璜'形象的原型。一个不断引诱女性又不断逃避后果的贵族——最终被石像拖入地狱。", gradient: "from-red-700 via-black to-gold-400" },

  // --- 非洲文学 (15+) ---
  { id: "x5-af-001", title: "阐释者", titleEn: "The Interpreters", author: "沃莱·索因卡", country: "尼日利亚", flag: "🇳🇬", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "哲学"], year: 1965, excerpt: "五个从欧美留学归来的尼日利亚知识分子在拉各斯的迷宫中寻找意义——一部关于后殖民非洲知识分子的'尤利西斯'。诺贝尔奖。", gradient: "from-blue-600 via-yellow-500 to-green-400" },
  { id: "x5-af-002", title: "开罗三部曲", titleEn: "The Cairo Trilogy", author: "纳吉布·马哈福兹", country: "埃及", flag: "🇪🇬", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史", "爱情"], year: 1957, excerpt: "以开罗一个中产家庭三代人的命运折射埃及从1919到1952年的社会变迁。阿拉伯文学的诺贝尔奖杰作。", gradient: "from-amber-600 via-sand-400 to-teal-300" },
  { id: "x5-af-003", title: "黑暗的孩子", titleEn: "The Dark Child", author: "卡马拉·莱耶", country: "几内亚", flag: "🇬🇳", continent: "africa", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "社会"], year: 1953, excerpt: "莱耶以诗意的笔触回忆在西非乡村度过的童年——打铁的父亲、传统的庆典、去法国的离别。珍贵的前殖民非洲生活记录。", gradient: "from-amber-500 via-gold-400 to-green-300" },
  { id: "x5-af-004", title: "独立的太阳", titleEn: "The Suns of Independence", author: "阿马杜·库鲁马", country: "科特迪瓦", flag: "🇨🇮", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "历史"], year: 1968, excerpt: "以独特的'马林凯法语'写成——库鲁马将非洲口语节奏注入了法语文学。独立后非洲——那些'独立的太阳'照亮了什么？", gradient: "from-red-500 via-yellow-400 to-green-300" },
  { id: "x5-af-005", title: "玛鲁", titleEn: "Maru", author: "贝西·黑德", country: "博茨瓦纳", flag: "🇧🇼", continent: "africa", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 1971, excerpt: "一个属于'不可接触者'阶层的年轻女教师在偏远村庄的故事——黑德以敏锐心理洞察揭示了种族偏见的内化。", gradient: "from-amber-500 via-brown-400 to-blue-300" },

  // --- 美洲文学 (15+) ---
  { id: "x5-am-001", title: "青年艺术家的画像", titleEn: "A Portrait of the Artist", author: "乔伊斯", country: "爱尔兰", flag: "🇮🇪", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学", "宗教"], year: 1916, excerpt: "斯蒂芬·迪达勒斯在都柏林的精神觉醒——从宗教禁锢到艺术自由的旅程。乔伊斯以意识流追踪艺术家灵魂孕育过程。", gradient: "from-green-600 via-white-300 to-orange-400" },
  { id: "x5-am-002", title: "剑锋", titleEn: "The Razor's Edge", author: "毛姆", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["小说"], themes: ["哲学", "心理", "社会"], year: 1944, excerpt: "拉里·达雷尔从一战归来后拒绝'正常'人生，踏上在印度寻找精神真理的旅程。毛姆探索了在物质主义时代追寻精神生活的可能。", gradient: "from-amber-400 via-white-200 to-teal-300" },
  { id: "x5-am-003", title: "星期六", titleEn: "Saturday", author: "伊恩·麦克尤恩", country: "英国", flag: "🇬🇧", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["心理", "社会"], year: 2005, excerpt: "神经外科医生亨利·佩罗恩在2003年2月15日的二十四小时——麦克尤恩以乔伊斯式的'一日叙事'包裹了后911时代的焦虑。", gradient: "from-blue-500 via-gray-300 to-red-200" },

  // --- 中东/其他 (15+) ---
  { id: "x5-me-001", title: "盲猫头鹰", titleEn: "The Blind Owl", author: "萨迪克·希达亚特", country: "伊朗", flag: "🇮🇷", continent: "asia", era: "现代 (1900—1950)", genre: ["小说"], themes: ["心理", "哲学", "魔幻"], year: 1937, excerpt: "伊朗现代文学中最阴郁最神秘的小说。一个孤独的画家在鸦片烟雾中反复描绘同一个场景——一个民族的灵魂暗夜。", gradient: "from-purple-800 via-black to-blue-700" },
  { id: "x5-me-002", title: "雪", titleEn: "Snow", author: "帕慕克", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["社会", "心理", "爱情"], year: 2002, excerpt: "诗人卡回到土耳其东部小城卡尔斯，大雪将他困在其中——一场关于军队、伊斯兰主义者和库尔德民族主义者的'微型内战'。", gradient: "from-white via-gray-200 to-blue-300" },
  { id: "x5-me-003", title: "我的名字叫红", titleEn: "My Name is Red", author: "帕慕克", country: "土耳其", flag: "🇹🇷", continent: "asia", era: "当代 (1950—)", genre: ["小说"], themes: ["哲学", "心理", "爱情"], year: 1998, excerpt: "十六世纪伊斯坦布尔——一张画、一桩谋杀案、多重视角叙述。将伊斯兰细密画美学辩论与侦探故事编织为后现代杰作。诺贝尔奖。", gradient: "from-red-700 via-gold-500 to-black" },

  // --- 大洋洲文学 (10+) ---
  { id: "x5-oc-001", title: "彩虹勇士", titleEn: "", author: "大卫·罗比", country: "新西兰", flag: "🇳🇿", continent: "oceania", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["社会", "自然", "历史"], year: 2005, excerpt: "记录了绿色和平组织旗舰'彩虹勇士号'被法国特工炸沉的真实事件——新西兰关于环保、反核与主权的重要非虚构。", gradient: "from-green-500 via-rainbow-400 to-blue-300" },

  // --- 诺贝尔/普利策/布克补完 (20+) ---
  { id: "x5-pr-001", title: "四个四重奏", titleEn: "Four Quartets", author: "T.S.艾略特", country: "英国", flag: "🇬🇧", continent: "europe", era: "现代 (1900—1950)", genre: ["诗歌"], themes: ["哲学", "宗教", "心理"], year: 1943, excerpt: "'时间现在和时间过去也许都存在于时间将来。'艾略特以四个乐章的诗篇对时间、信仰与人类存在进行了最深邃的沉思。诺贝尔奖1948。", gradient: "from-blue-500 via-purple-300 to-gold-200" },
  { id: "x5-pr-002", title: "天使游戏", titleEn: "The Angel's Game", author: "萨丰", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["魔幻", "心理", "爱情"], year: 2008, excerpt: "1920年代巴塞罗那——落魄作家接受了一个神秘出版商的委托。萨丰在'遗忘书之墓'系列中建造了献给书籍的哥特迷宫。", gradient: "from-blue-800 via-purple-700 to-black" },
  { id: "x5-pr-003", title: "根特祭坛画", titleEn: "The Ghent Altarpiece", author: "彼得·范登贝尔赫", country: "荷兰", flag: "🇳🇱", continent: "europe", era: "当代 (1950—)", genre: ["小说"], themes: ["历史", "哲学"], year: 2005, excerpt: "以凡艾克兄弟的名画为线索穿越几个世纪的欧洲艺术与战争史——一幅画所见证的人类文明的光辉与黑暗。", gradient: "from-gold-500 via-blue-400 to-green-300" },
  { id: "x5-pr-004", title: "血的婚礼", titleEn: "Blood Wedding", author: "洛尔迦", country: "西班牙", flag: "🇪🇸", continent: "europe", era: "现代 (1900—1950)", genre: ["戏剧"], themes: ["爱情", "社会", "自然"], year: 1933, excerpt: "安达卢西亚'乡村三部曲'之首。一场婚礼变成了复仇的血案——洛尔迦以诗的密度将西班牙民间谣曲节奏注入戏剧的血脉。", gradient: "from-red-600 via-black to-white" },
  { id: "x5-pr-005", title: "与魔鬼的斗争", titleEn: "The Struggle with the Demon", author: "斯蒂芬·茨威格", country: "奥地利", flag: "🇦🇹", continent: "europe", era: "现代 (1900—1950)", genre: ["散文/随笔"], themes: ["心理", "哲学"], year: 1925, excerpt: "赫尔德林、克莱斯特、尼采——三个被'魔鬼'(创造力本身)吞噬的天才。茨威格以心理分析的深度为这三个灵魂画像。", gradient: "from-purple-600 via-red-500 to-gold-400" },
  { id: "x5-pr-006", title: "德国人的历史", titleEn: "The Germans", author: "戈洛·曼", country: "德国", flag: "🇩🇪", continent: "europe", era: "当代 (1950—)", genre: ["散文/随笔"], themes: ["历史", "哲学"], year: 1978, excerpt: "二十世纪最重要的历史散文之一——戈洛·曼以文学家的笔触书写了德意志民族一千年的精神历程。", gradient: "from-black via-red-600 to-gold-400" },
  { id: "x5-pr-007", title: "非洲的绿山", titleEn: "Green Hills of Africa", author: "海明威", country: "美国", flag: "🇺🇸", continent: "americas", era: "现代 (1900—1950)", genre: ["散文/随笔"], themes: ["自然", "冒险"], year: 1935, excerpt: "海明威在东非狩猎旅行的非虚构叙事——除了狩猎之外，关于写作本身最坦诚的自白。", gradient: "from-green-600 via-amber-500 to-brown-400" },
];
